function design(site, analyse) {
  const xs = [0, 2.571, 5.143, 7.714, 10.286, 12.857, 15.429, 18];
  const bottomY = -2.58;
  const note = "A deep, all-pinned Pratt truss keeps the structure below the crane path; sections were swept for nominal safety margins.";
  const nodes = xs.map((x, i) => ({ id: "B" + i, x: x, y: bottomY, joint: "pin" }));

  const areas = {
    "CHS88.9x5": 13.18, "CHS114.3x5": 17.17,
    "CHS139.7x6.3": 26.4, "CHS168.3x6.3": 32.06,
    "CHS193.7x8": 46.67, "CHS219.1x8": 53.06,
    "CHS244.5x8": 59.44, "CHS273x10": 82.62,
    "CHS323.9x10": 98.61, "CHS355.6x12.5": 134.74,
    "CHS406.4x12.5": 154.68
  };

  function make(c) {
    const members = [];
    function add(a, b, section) {
      members.push([a, b, "S460 " + section]);
    }

    for (let i = 0; i < 7; i++) {
      add("D" + i, "D" + (i + 1), c.top);
      add("B" + i, "B" + (i + 1), c.bottom);
    }
    for (let i = 0; i < 8; i++) add("D" + i, "B" + i, c.vertical);

    // Pratt diagonals slope toward the centre of the span.
    for (let i = 0; i <= 3; i++) add("D" + i, "B" + (i + 1), c.diagonal);
    for (let i = 4; i <= 6; i++) add("B" + i, "D" + (i + 1), c.diagonal);

    return { note: note, nodes: nodes, joints: {}, members: members };
  }

  function isNum(x) {
    return typeof x === "number" && isFinite(x);
  }

  function fatigueRatio(x) {
    if (isNum(x)) return x > 3 ? x / 52.6 : x;

    if (Array.isArray(x)) {
      let best = null;
      for (const item of x) {
        const r = fatigueRatio(item);
        if (isNum(r) && (best === null || r > best)) best = r;
      }
      return best;
    }

    if (!x || typeof x !== "object") return null;

    let util = null, stress = null, limit = null;
    for (const key of Object.keys(x)) {
      const k = key.toLowerCase();
      const value = x[key];
      if (!isNum(value)) continue;

      if (k.includes("util") || k.includes("ratio") ||
          k.includes("unity") || k.includes("usage")) {
        util = value;
      } else if (k.includes("limit") || k.includes("allow") ||
                 k.includes("capacity")) {
        limit = value;
      } else if (k.includes("stress") || k.includes("range") ||
                 k.includes("delta")) {
        stress = value;
      }
    }

    if (util !== null) return util;
    if (stress !== null && limit !== null && limit > 0) return stress / limit;
    if (stress !== null) return stress / 52.6;

    let best = null;
    for (const key of Object.keys(x)) {
      const r = fatigueRatio(x[key]);
      if (isNum(r) && (best === null || r > best)) best = r;
    }
    return best;
  }

  function risk(r) {
    let q = 0;
    if (isNum(r.maxUtil)) q = Math.max(q, r.maxUtil / 0.75);
    if (isNum(r.sag) && isNum(r.sagLimit) && r.sagLimit > 0) {
      q = Math.max(q, (r.sag / r.sagLimit) / 0.82);
    }
    if (isNum(r.frequency) && isNum(r.fMin) && r.frequency > 0) {
      q = Math.max(q, (1.12 * r.fMin) / r.frequency);
    }
    const fr = fatigueRatio(r.fatigueWorst);
    if (isNum(fr)) q = Math.max(q, fr / 0.84);
    return q;
  }

  function cost(r) {
    if (isNum(r.mass)) return r.mass;
    if (isNum(r.score) && r.score > 0) return 1 / r.score;
    return Infinity;
  }

  const topSections = [
    "CHS273x10", "CHS323.9x10", "CHS355.6x12.5", "CHS406.4x12.5"
  ];
  const bottomSections = [
    "CHS244.5x8", "CHS273x10", "CHS323.9x10", "CHS355.6x12.5"
  ];
  const verticalSections = [
    "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3", "CHS168.3x6.3"
  ];
  const diagonalSections = [
    "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x8",
    "CHS219.1x8", "CHS273x10", "CHS323.9x10"
  ];

  const base = {
    top: "CHS406.4x12.5",
    bottom: "CHS355.6x12.5",
    vertical: "CHS168.3x6.3",
    diagonal: "CHS323.9x10"
  };
  const baseKey = [base.top, base.bottom, base.vertical, base.diagonal].join("|");

  let bestRobust = null;
  let bestOK = null;
  let bestAny = null;
  let bestAnyRisk = Infinity;
  let calls = 0;
  const start = Date.now();

  function evaluate(c) {
    let result;
    try {
      result = analyse(make(c));
    } catch (e) {
      return;
    }
    calls++;
    if (!result || result.error) return;

    const q = risk(result);
    const entry = { design: make(c), result: result };

    if (q < bestAnyRisk || bestAny === null) {
      bestAnyRisk = q;
      bestAny = entry;
    }

    if (result.ok === true) {
      if (bestOK === null || cost(result) < cost(bestOK.result)) bestOK = entry;
      if (q <= 1 && (bestRobust === null ||
                     cost(result) < cost(bestRobust.result))) {
        bestRobust = entry;
      }
    }
  }

  // Keep a conservative fallback available before trying lighter options.
  evaluate(base);

  const candidates = [];
  for (const t of topSections) {
    for (const b of bottomSections) {
      for (const v of verticalSections) {
        for (const d of diagonalSections) {
          const c = { top: t, bottom: b, vertical: v, diagonal: d };
          if ([t, b, v, d].join("|") === baseKey) continue;
          const estimate =
            18 * (areas[t] + areas[b]) +
            20.64 * areas[v] +
            7 * Math.sqrt(2.571 * 2.571 + 2.58 * 2.58) * areas[d] +
            0.7 * (7 * areas[t] + 7 * areas[b] + 8 * areas[v] + 7 * areas[d]);
          candidates.push({ c: c, estimate: estimate });
        }
      }
    }
  }
  candidates.sort((a, b) => a.estimate - b.estimate);

  for (const item of candidates) {
    if (calls >= 399 || Date.now() - start > 78000) break;
    evaluate(item.c);
  }

  if (bestRobust) return bestRobust.design;
  if (bestOK) return bestOK.design;
  if (bestAny) return bestAny.design;
  return make(base);
}

function design(site, analyse) {
  const started = Date.now();
  const maxCalls = 380;
  const maxMillis = 78000;
  let calls = 0;

  const xs = [0, 2.571, 5.143, 7.714, 10.286, 12.857, 15.429, 18];
  const depth = 2.58;

  const areas = {
    "CHS33.7x2.6": 2.54, "CHS42.4x3.2": 3.94,
    "CHS48.3x3.2": 4.53, "CHS60.3x3.2": 5.74,
    "CHS60.3x4": 7.07, "CHS76.1x3.2": 7.33,
    "CHS76.1x4": 9.06, "CHS88.9x4": 10.67,
    "CHS88.9x5": 13.18, "CHS114.3x4": 13.86,
    "CHS114.3x5": 17.17, "CHS139.7x5": 21.16,
    "CHS139.7x6.3": 26.4, "CHS168.3x5": 25.65,
    "CHS168.3x6.3": 32.06, "CHS193.7x6.3": 37.09,
    "CHS193.7x8": 46.67, "CHS219.1x8": 53.06,
    "CHS244.5x8": 59.44, "CHS273x10": 82.62,
    "CHS323.9x10": 98.61, "CHS355.6x12.5": 134.74,
    "CHS406.4x12.5": 154.68, "CHS457x16": 221.67
  };

  const allSections = Object.keys(areas).sort(function(a, b) {
    return areas[a] - areas[b];
  });
  const sectionIndex = {};
  for (let i = 0; i < allSections.length; i++) {
    sectionIndex[allSections[i]] = i;
  }

  const roles = ["top", "bottom", "vertical", "diagonal"];

  function fill(value, n) {
    const a = [];
    for (let i = 0; i < n; i++) a.push(value);
    return a;
  }

  function defaultMats(mats) {
    const out = {};
    for (let i = 0; i < roles.length; i++) {
      const r = roles[i];
      out[r] = mats && mats[r] ? mats[r] : "S460";
    }
    return out;
  }

  function uniformState(kind, top, bottom, vertical, diagonal, mats) {
    return {
      kind: kind,
      top: fill(top, 7),
      bottom: fill(bottom, kind === "P" ? 7 : 6),
      vertical: kind === "P" ? fill(vertical, 8) : [],
      diagonal: fill(diagonal, kind === "P" ? 7 : 14),
      mats: defaultMats(mats)
    };
  }

  function cloneState(s) {
    return {
      kind: s.kind,
      top: s.top.slice(),
      bottom: s.bottom.slice(),
      vertical: s.vertical.slice(),
      diagonal: s.diagonal.slice(),
      mats: defaultMats(s.mats)
    };
  }

  function stateKey(s) {
    return s.kind + "|" +
      s.top.join(",") + "|" +
      s.bottom.join(",") + "|" +
      s.vertical.join(",") + "|" +
      s.diagonal.join(",") + "|" +
      roles.map(function(r) { return s.mats[r]; }).join(",");
  }

  function makePratt(s) {
    const nodes = [];
    for (let i = 0; i < xs.length; i++) {
      nodes.push({ id: "B" + i, x: xs[i], y: -depth, joint: "pin" });
    }

    const members = [];
    function add(a, b, role, sec) {
      members.push([a, b, s.mats[role] + " " + sec]);
    }

    for (let i = 0; i < 7; i++) {
      add("D" + i, "D" + (i + 1), "top", s.top[i]);
      add("B" + i, "B" + (i + 1), "bottom", s.bottom[i]);
    }
    for (let i = 0; i < 8; i++) {
      add("D" + i, "B" + i, "vertical", s.vertical[i]);
    }
    for (let i = 0; i <= 3; i++) {
      add("D" + i, "B" + (i + 1), "diagonal", s.diagonal[i]);
    }
    for (let i = 4; i <= 6; i++) {
      add("B" + i, "D" + (i + 1), "diagonal", s.diagonal[i]);
    }

    return {
      note: "A deep, all-pinned Pratt layout retains a direct load path with fatigue-sized web members.",
      nodes: nodes,
      joints: {},
      members: members
    };
  }

  function makeWarren(s) {
    const nodes = [];
    for (let i = 0; i < 7; i++) {
      nodes.push({
        id: "W" + i,
        x: (xs[i] + xs[i + 1]) / 2,
        y: -depth,
        joint: "pin"
      });
    }

    const members = [];
    function add(a, b, role, sec) {
      members.push([a, b, s.mats[role] + " " + sec]);
    }

    for (let i = 0; i < 7; i++) {
      add("D" + i, "D" + (i + 1), "top", s.top[i]);
    }
    for (let i = 0; i < 6; i++) {
      add("W" + i, "W" + (i + 1), "bottom", s.bottom[i]);
    }
    for (let i = 0; i < 7; i++) {
      add("D" + i, "W" + i, "diagonal", s.diagonal[2 * i]);
      add("D" + (i + 1), "W" + i, "diagonal", s.diagonal[2 * i + 1]);
    }

    return {
      note: "Panel-centred Warren triangles remove the fatigue-prone verticals and share deck loads through pinned diagonals.",
      nodes: nodes,
      joints: {},
      members: members
    };
  }

  function make(s) {
    return s.kind === "P" ? makePratt(s) : makeWarren(s);
  }

  function estimateMass(s) {
    let lengthArea = 0;
    let memberArea = 0;

    function add(sec, length) {
      const a = areas[sec] || 0;
      lengthArea += a * length;
      memberArea += a;
    }

    if (s.kind === "P") {
      for (let i = 0; i < 7; i++) {
        const panel = xs[i + 1] - xs[i];
        add(s.top[i], panel);
        add(s.bottom[i], panel);
      }
      for (let i = 0; i < 8; i++) add(s.vertical[i], depth);
      for (let i = 0; i < 7; i++) {
        const panel = xs[i + 1] - xs[i];
        add(s.diagonal[i], Math.sqrt(panel * panel + depth * depth));
      }
      return 0.785 * (lengthArea + 0.7 * memberArea) + 16 * 12;
    }

    for (let i = 0; i < 7; i++) {
      const panel = xs[i + 1] - xs[i];
      add(s.top[i], panel);
    }
    for (let i = 0; i < 6; i++) {
      const x0 = (xs[i] + xs[i + 1]) / 2;
      const x1 = (xs[i + 1] + xs[i + 2]) / 2;
      add(s.bottom[i], x1 - x0);
    }
    for (let i = 0; i < 7; i++) {
      const half = (xs[i + 1] - xs[i]) / 2;
      const diagonalLength = Math.sqrt(half * half + depth * depth);
      add(s.diagonal[2 * i], diagonalLength);
      add(s.diagonal[2 * i + 1], diagonalLength);
    }
    return 0.785 * (lengthArea + 0.7 * memberArea) + 15 * 12;
  }

  function isNum(x) {
    return typeof x === "number" && isFinite(x);
  }

  function fatigueRatio(x) {
    if (isNum(x)) return x > 3 ? x / 52.6 : x;

    if (Array.isArray(x)) {
      let best = null;
      for (let i = 0; i < x.length; i++) {
        const r = fatigueRatio(x[i]);
        if (isNum(r) && (best === null || r > best)) best = r;
      }
      return best;
    }

    if (!x || typeof x !== "object") return null;

    let util = null;
    let stress = null;
    let limit = null;

    for (const key of Object.keys(x)) {
      const k = key.toLowerCase();
      const value = x[key];
      if (!isNum(value)) continue;

      if (k.includes("util") || k.includes("ratio") ||
          k.includes("unity") || k.includes("usage")) {
        if (util === null || value > util) util = value;
      } else if (k.includes("limit") || k.includes("allow") ||
                 k.includes("capacity")) {
        limit = value;
      } else if (k.includes("stress") || k.includes("range") ||
                 k.includes("delta")) {
        stress = value;
      }
    }

    if (util !== null) return util;
    if (stress !== null && limit !== null && limit > 0) return stress / limit;
    if (stress !== null) return stress / 52.6;

    let best = null;
    for (const key of Object.keys(x)) {
      const r = fatigueRatio(x[key]);
      if (isNum(r) && (best === null || r > best)) best = r;
    }
    return best;
  }

  function failureText(x) {
    if (x === null || x === undefined || x === false || x === "") return "";
    if (typeof x === "string") return x.trim().toLowerCase();
    if (Array.isArray(x)) {
      let out = "";
      for (let i = 0; i < x.length; i++) out += " " + failureText(x[i]);
      return out.trim();
    }
    if (typeof x === "object") {
      let out = "";
      for (const key of Object.keys(x)) {
        out += " " + key + " " + failureText(x[key]);
      }
      return out.trim();
    }
    return String(x).toLowerCase();
  }

  function metrics(r) {
    let maxUtil = isNum(r.maxUtil) ? r.maxUtil : null;
    if (maxUtil === null && Array.isArray(r.cases)) {
      for (let i = 0; i < r.cases.length; i++) {
        const u = r.cases[i].maxUtil;
        if (isNum(u) && (maxUtil === null || u > maxUtil)) maxUtil = u;
      }
    }
    if (maxUtil === null) maxUtil = Infinity;

    let fr = fatigueRatio(r.fatigueWorst);
    if (!isNum(fr)) fr = Infinity;

    let sagRatio = 0;
    const sagLimit = isNum(r.sagLimit) && r.sagLimit > 0 ? r.sagLimit : 45;
    if (isNum(r.sag)) {
      sagRatio = r.sag / sagLimit;
    } else if (Array.isArray(r.cases)) {
      let largestSag = 0;
      for (let i = 0; i < r.cases.length; i++) {
        if (isNum(r.cases[i].sag)) largestSag = Math.max(largestSag, r.cases[i].sag);
      }
      sagRatio = largestSag / sagLimit;
    }

    const fMin = isNum(r.fMin) && r.fMin > 0 ? r.fMin : 4.5;
    const frequency = isNum(r.frequency) && r.frequency > 0 ? r.frequency : 0;

    const q = Math.max(
      maxUtil / 0.60,
      fr / 0.75,
      sagRatio / 0.75,
      frequency > 0 ? 1.18 * fMin / frequency : Infinity
    );

    const f = failureText(r.failure);
    const hasFailure = f !== "" && f !== "none" && f !== "ok" &&
                       f !== "pass" && f !== "passed" && f !== "no failure";

    return {
      q: q,
      safe: r.ok === true && !hasFailure && q <= 1,
      mass: isNum(r.mass) ? r.mass : Infinity
    };
  }

  const seen = {};
  let bestRobust = null;
  let bestNear = null;

  function withinBudget() {
    return calls < maxCalls && Date.now() - started < maxMillis;
  }

  function evaluate(s) {
    const key = stateKey(s);
    if (seen[key]) return seen[key];
    if (!withinBudget()) return null;

    const snap = cloneState(s);
    let result;
    try {
      result = analyse(make(snap));
      calls++;
    } catch (e) {
      calls++;
      seen[key] = null;
      return null;
    }

    if (!result || result.error) {
      seen[key] = null;
      return null;
    }

    const m = metrics(result);
    const entry = {
      state: snap,
      result: result,
      q: m.q,
      safe: m.safe,
      mass: isNum(result.mass) ? result.mass : estimateMass(snap)
    };
    seen[key] = entry;

    if (entry.safe) {
      if (!bestRobust || entry.mass < bestRobust.mass) bestRobust = entry;
    }
    if (!bestNear || entry.q < bestNear.q ||
        (entry.q === bestNear.q && entry.mass < bestNear.mass)) {
      bestNear = entry;
    }
    return entry;
  }

  function addSeeds(kind, rows) {
    for (let i = 0; i < rows.length && withinBudget(); i++) {
      const row = rows[i];
      evaluate(uniformState(kind, row[0], row[1], row[2], row[3], row[4]));
    }
  }

  addSeeds("P", [
    ["CHS193.7x8", "CHS139.7x6.3", "CHS273x10", "CHS168.3x6.3"],
    ["CHS193.7x8", "CHS139.7x6.3", "CHS323.9x10", "CHS168.3x6.3"],
    ["CHS193.7x8", "CHS139.7x6.3", "CHS323.9x10", "CHS193.7x8"],
    ["CHS168.3x6.3", "CHS139.7x6.3", "CHS323.9x10", "CHS193.7x8"],
    ["CHS193.7x8", "CHS168.3x6.3", "CHS323.9x10", "CHS193.7x8"],
    ["CHS219.1x8", "CHS168.3x6.3", "CHS323.9x10", "CHS193.7x8"],
    ["CHS193.7x8", "CHS139.7x6.3", "CHS273x10", "CHS219.1x8"],
    ["CHS168.3x6.3", "CHS114.3x5", "CHS323.9x10", "CHS219.1x8"],
    ["CHS219.1x8", "CHS193.7x8", "CHS323.9x10", "CHS219.1x8"],
    ["CHS244.5x8", "CHS193.7x8", "CHS355.6x12.5", "CHS193.7x8"],
    ["CHS168.3x6.3", "CHS139.7x6.3", "CHS355.6x12.5", "CHS168.3x6.3"],
    ["CHS244.5x8", "CHS219.1x8", "CHS323.9x10", "CHS244.5x8"]
  ]);

  addSeeds("W", [
    ["CHS168.3x6.3", "CHS139.7x6.3", "", "CHS219.1x8"],
    ["CHS193.7x8", "CHS168.3x6.3", "", "CHS219.1x8"],
    ["CHS193.7x8", "CHS168.3x6.3", "", "CHS244.5x8"],
    ["CHS168.3x6.3", "CHS139.7x6.3", "", "CHS244.5x8"],
    ["CHS219.1x8", "CHS168.3x6.3", "", "CHS244.5x8"],
    ["CHS193.7x8", "CHS139.7x6.3", "", "CHS273x10"],
    ["CHS219.1x8", "CHS193.7x8", "", "CHS244.5x8"],
    ["CHS244.5x8", "CHS193.7x8", "", "CHS244.5x8"],
    ["CHS168.3x6.3", "CHS139.7x6.3", "", "CHS193.7x8"],
    ["CHS193.7x8", "CHS168.3x6.3", "", "CHS273x10"],
    ["CHS219.1x8", "CHS168.3x6.3", "", "CHS273x10"],
    ["CHS244.5x8", "CHS219.1x8", "", "CHS273x10"]
  ]);

  const s690 = {
    top: "S690",
    bottom: "S690",
    vertical: "S460",
    diagonal: "S460"
  };
  evaluate(uniformState("P", "CHS139.7x6.3", "CHS139.7x6.3",
                        "CHS273x10", "CHS323.9x10", s690));
  evaluate(uniformState("P", "CHS139.7x6.3", "CHS139.7x6.3",
                        "CHS323.9x10", "CHS273x10", s690));
  evaluate(uniformState("P", "CHS139.7x6.3", "CHS139.7x6.3",
                        "CHS323.9x10", "CHS323.9x10", s690));
  evaluate(uniformState("W", "CHS139.7x6.3", "CHS139.7x6.3",
                        "", "CHS244.5x8", s690));
  evaluate(uniformState("W", "CHS139.7x6.3", "CHS168.3x6.3",
                        "", "CHS273x10", s690));

  function grid(kind, topOptions, bottomOptions, verticalOptions, diagonalOptions) {
    const list = [];
    for (let ti = 0; ti < topOptions.length; ti++) {
      for (let bi = 0; bi < bottomOptions.length; bi++) {
        for (let vi = 0; vi < verticalOptions.length; vi++) {
          for (let di = 0; di < diagonalOptions.length; di++) {
            const s = uniformState(kind, topOptions[ti], bottomOptions[bi],
                                   verticalOptions[vi], diagonalOptions[di]);
            list.push({ state: s, estimate: estimateMass(s) });
          }
        }
      }
    }
    list.sort(function(a, b) { return a.estimate - b.estimate; });
    return list;
  }

  function sampleGrid(list, count) {
    if (!list.length) return;
    const nLow = Math.floor(count * 0.38);
    const lowEnd = Math.floor((list.length - 1) * 0.22);

    for (let i = 0; i < nLow && withinBudget(); i++) {
      const rank = nLow <= 1 ? 0 : Math.round(i * lowEnd / (nLow - 1));
      evaluate(list[rank].state);
    }
    const remaining = count - nLow;
    for (let i = 0; i < remaining && withinBudget(); i++) {
      const f = remaining <= 1 ? 0 : i / (remaining - 1);
      const rank = Math.round(lowEnd + f * ((list.length - 1) * 0.95 - lowEnd));
      evaluate(list[Math.min(list.length - 1, rank)].state);
    }
  }

  const pTop = [
    "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3", "CHS168.3x6.3",
    "CHS193.7x8", "CHS219.1x8", "CHS244.5x8", "CHS273x10",
    "CHS323.9x10"
  ];
  const pBottom = [
    "CHS76.1x4", "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3",
    "CHS168.3x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8"
  ];
  const pVertical = [
    "CHS168.3x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8",
    "CHS273x10", "CHS323.9x10", "CHS355.6x12.5"
  ];
  const pDiagonal = [
    "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3", "CHS168.3x6.3",
    "CHS193.7x8", "CHS219.1x8", "CHS244.5x8", "CHS273x10",
    "CHS323.9x10"
  ];

  const wTop = [
    "CHS76.1x4", "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3",
    "CHS168.3x6.3", "CHS193.7x8", "CHS219.1x8", "CHS244.5x8",
    "CHS273x10"
  ];
  const wBottom = [
    "CHS60.3x4", "CHS76.1x4", "CHS88.9x5", "CHS114.3x5",
    "CHS139.7x6.3", "CHS168.3x6.3", "CHS193.7x8", "CHS219.1x8"
  ];
  const wDiagonal = [
    "CHS88.9x5", "CHS114.3x5", "CHS139.7x6.3", "CHS168.3x6.3",
    "CHS193.7x8", "CHS219.1x8", "CHS244.5x8", "CHS273x10",
    "CHS323.9x10"
  ];

  sampleGrid(grid("P", pTop, pBottom, pVertical, pDiagonal), 140);
  sampleGrid(grid("W", wTop, wBottom, [""], wDiagonal), 110);

  function refine(entry) {
    if (!entry) return;
    let current = entry;
    let state = cloneState(entry.state);
    const groups = ["top", "bottom", "vertical", "diagonal"];

    for (let g = 0; g < groups.length && withinBudget(); g++) {
      const group = groups[g];
      for (let i = 0; i < state[group].length && withinBudget(); i++) {
        let idx = sectionIndex[state[group][i]];
        while (idx > 0 && withinBudget()) {
          const trial = cloneState(state);
          trial[group][i] = allSections[idx - 1];
          const e = evaluate(trial);
          if (e && e.safe && e.mass < current.mass) {
            current = e;
            state = cloneState(e.state);
            idx = sectionIndex[state[group][i]];
          } else {
            break;
          }
        }
      }
    }
  }

  function repair(entry) {
    if (!entry) return;
    let current = entry;
    const maxRepairIndex = sectionIndex["CHS355.6x12.5"];

    for (let step = 0; step < 5 && withinBudget() && !current.safe; step++) {
      let winner = null;
      for (let g = 0; g < roles.length && withinBudget(); g++) {
        const group = roles[g];
        const trial = cloneState(current.state);
        let changed = false;
        for (let i = 0; i < trial[group].length; i++) {
          const idx = sectionIndex[trial[group][i]];
          if (idx < maxRepairIndex) {
            trial[group][i] = allSections[idx + 1];
            changed = true;
          }
        }
        if (!changed) continue;
        const e = evaluate(trial);
        if (e && (!winner || e.q < winner.q ||
                  (e.q === winner.q && e.mass < winner.mass))) {
          winner = e;
        }
      }
      if (!winner || (winner.q >= current.q && !winner.safe)) break;
      current = winner;
    }
  }

  if (!bestRobust) repair(bestNear);
  if (bestRobust) refine(bestRobust);

  if (bestRobust) return make(bestRobust.state);
  if (bestNear) return make(bestNear.state);

  return make(uniformState(
    "P", "CHS219.1x8", "CHS193.7x8",
    "CHS323.9x10", "CHS273x10"
  ));
}

function design(site, analyse) {
  const started = Date.now();
  const maxCalls = 390;
  const maxMillis = 78000;
  let calls = 0;

  const xs = [0, 2.571, 5.143, 7.714, 10.286, 12.857, 15.429, 18];
  const note =
    "A pinned, under-deck GL28 truss uses member-specific sizing to exploit timber’s low density while retaining margins for fatigue, strength, and deflection.";

  const timberData = [
    ["TIMBER90x180", 162, 180],
    ["TIMBER115x225", 258.75, 225],
    ["TIMBER140x270", 378, 270],
    ["TIMBER160x315", 504, 315],
    ["TIMBER190x360", 684, 360],
    ["TIMBER190x450", 855, 450],
    ["TIMBER215x540", 1161, 540],
    ["TIMBER240x630", 1512, 630],
    ["TIMBER280x720", 2016, 720],
    ["TIMBER320x900", 2880, 900]
  ];

  const timber = [];
  const timberByName = Object.create(null);
  for (let i = 0; i < timberData.length; i++) {
    const item = {
      id: timberData[i][0],
      spec: "GL28 " + timberData[i][0],
      area: timberData[i][1],
      depth: timberData[i][2],
      density: 420,
      index: i
    };
    timber.push(item);
    timberByName[item.id] = item;
  }

  function isNum(x) {
    return typeof x === "number" && isFinite(x);
  }

  function edgesFor(kind) {
    const edges = [];
    function add(a, b, role) {
      edges.push({ a: a, b: b, role: role });
    }

    if (kind === "P") {
      for (let i = 0; i < 7; i++) add("D" + i, "D" + (i + 1), "top");
      for (let i = 0; i < 7; i++) add("B" + i, "B" + (i + 1), "bottom");
      for (let i = 0; i < 8; i++) add("D" + i, "B" + i, "vertical");
      for (let i = 0; i <= 3; i++) add("D" + i, "B" + (i + 1), "diagonal");
      for (let i = 4; i <= 6; i++) add("B" + i, "D" + (i + 1), "diagonal");
      return edges;
    }

    for (let i = 0; i < 7; i++) add("D" + i, "D" + (i + 1), "top");
    for (let i = 0; i < 6; i++) add("W" + i, "W" + (i + 1), "bottom");
    for (let i = 0; i < 7; i++) {
      add("D" + i, "W" + i, "diagonal");
      add("D" + (i + 1), "W" + i, "diagonal");
    }
    return edges;
  }

  function bottomNames(kind) {
    const names = [];
    const count = kind === "P" ? 8 : 7;
    const prefix = kind === "P" ? "B" : "W";
    for (let i = 0; i < count; i++) names.push(prefix + i);
    return names;
  }

  function cloneState(s) {
    return { kind: s.kind, options: s.options.slice() };
  }

  function stateKey(s) {
    return s.kind + "|" + s.options.map(function(o) { return o.id; }).join(",");
  }

  function makeState(kind, sizes) {
    const edges = edgesFor(kind);
    return {
      kind: kind,
      options: edges.map(function(e) {
        return timberByName[sizes[e.role]];
      })
    };
  }

  function makeDesign(s) {
    const lower = bottomNames(s.kind);
    let maxDepth = 180;
    for (let i = 0; i < s.options.length; i++) {
      maxDepth = Math.max(maxDepth, s.options[i].depth);
    }

    // Keep the member envelope inside the lower site boundary.
    const bottomY = -2.77 + maxDepth / 2000 + 0.015;
    const nodes = [];
    const coords = Object.create(null);

    for (let i = 0; i < xs.length; i++) {
      coords["D" + i] = { x: xs[i], y: 0 };
    }

    for (let i = 0; i < lower.length; i++) {
      const x = s.kind === "P"
        ? xs[i]
        : (xs[i] + xs[i + 1]) / 2;
      coords[lower[i]] = { x: x, y: bottomY };
      nodes.push({ id: lower[i], x: x, y: bottomY, joint: "pin" });
    }

    const edges = edgesFor(s.kind);
    const members = edges.map(function(e, i) {
      return [e.a, e.b, s.options[i].spec];
    });

    return {
      note: note,
      nodes: nodes,
      joints: {},
      members: members
    };
  }

  function estimatedMass(s) {
    const lower = bottomNames(s.kind);
    let maxDepth = 180;
    for (let i = 0; i < s.options.length; i++) {
      maxDepth = Math.max(maxDepth, s.options[i].depth);
    }
    const bottomY = -2.77 + maxDepth / 2000 + 0.015;
    const coords = Object.create(null);

    for (let i = 0; i < xs.length; i++) {
      coords["D" + i] = { x: xs[i], y: 0 };
    }
    for (let i = 0; i < lower.length; i++) {
      coords[lower[i]] = {
        x: s.kind === "P" ? xs[i] : (xs[i] + xs[i + 1]) / 2,
        y: bottomY
      };
    }

    let mass = 12 * (8 + lower.length);
    const edges = edgesFor(s.kind);
    for (let i = 0; i < edges.length; i++) {
      const e = edges[i];
      const o = s.options[i];
      const dx = coords[e.a].x - coords[e.b].x;
      const dy = coords[e.a].y - coords[e.b].y;
      const length = Math.sqrt(dx * dx + dy * dy);
      const linearMass = o.density * o.area / 10000;
      mass += linearMass * (length + 0.7);
    }
    return mass;
  }

  function fatigueRatio(x) {
    if (isNum(x)) return x > 2 ? x / 4.678 : x;

    if (Array.isArray(x)) {
      let best = null;
      for (let i = 0; i < x.length; i++) {
        const r = fatigueRatio(x[i]);
        if (isNum(r) && (best === null || r > best)) best = r;
      }
      return best;
    }

    if (!x || typeof x !== "object") return null;

    let util = null;
    let stress = null;
    let limit = null;

    for (const key of Object.keys(x)) {
      const k = key.toLowerCase();
      const value = x[key];
      if (!isNum(value)) continue;

      if (k.includes("util") || k.includes("ratio") ||
          k.includes("unity") || k.includes("usage")) {
        if (util === null || value > util) util = value;
      } else if (k.includes("limit") || k.includes("allow") ||
                 k.includes("capacity")) {
        limit = value;
      } else if (k.includes("stress") || k.includes("range") ||
                 k.includes("delta")) {
        stress = value;
      }
    }

    if (util !== null) return util;
    if (stress !== null && limit !== null && limit > 0) return stress / limit;
    if (stress !== null) return stress / 4.678;

    let best = null;
    for (const key of Object.keys(x)) {
      const r = fatigueRatio(x[key]);
      if (isNum(r) && (best === null || r > best)) best = r;
    }
    return best;
  }

  function metrics(r, s) {
    let uls = isNum(r.maxUtil) ? r.maxUtil : null;
    if (Array.isArray(r.cases)) {
      for (let i = 0; i < r.cases.length; i++) {
        const u = r.cases[i] && r.cases[i].maxUtil;
        if (isNum(u) && (uls === null || u > uls)) uls = u;
      }
    }
    if (uls === null) uls = Infinity;

    let fatigue = fatigueRatio(r.fatigueWorst);
    if (!isNum(fatigue) && Array.isArray(r.members)) {
      fatigue = null;
      for (let i = 0; i < r.members.length; i++) {
        const m = r.members[i];
        if (m && String(m.mode || "").toLowerCase().includes("fatigue") &&
            isNum(m.util)) {
          if (fatigue === null || m.util > fatigue) fatigue = m.util;
        }
      }
    }
    if (!isNum(fatigue)) fatigue = Infinity;

    let sag = isNum(r.sag) ? Math.abs(r.sag) : null;
    if (Array.isArray(r.cases)) {
      for (let i = 0; i < r.cases.length; i++) {
        const v = r.cases[i] && r.cases[i].sag;
        if (isNum(v)) sag = sag === null ? Math.abs(v) : Math.max(sag, Math.abs(v));
      }
    }
    const sagLimit = isNum(r.sagLimit) && r.sagLimit > 0 ? r.sagLimit : 45;
    const sagRatio = sag === null ? Infinity : sag / sagLimit;

    const fMin = isNum(r.fMin) && r.fMin > 0 ? r.fMin : 4.5;
    const frequency = isNum(r.frequency) && r.frequency > 0 ? r.frequency : 0;

    // Nominal margins allow for timber strength, stiffness, and dimensional draws.
    const q = Math.max(
      fatigue / 0.92,
      uls / 0.78,
      sagRatio / 0.80,
      frequency > 0 ? (1.20 * fMin) / frequency : Infinity
    );

    return {
      q: q,
      robust: r.ok === true && q <= 1,
      pass: r.ok === true,
      mass: isNum(r.mass) ? r.mass : estimatedMass(s)
    };
  }

  const seen = Object.create(null);
  let bestRobust = null;
  let bestPass = null;
  let bestNear = null;
  const bestByKind = Object.create(null);

  function withinBudget() {
    return calls < maxCalls && Date.now() - started < maxMillis;
  }

  function evaluate(s) {
    const key = stateKey(s);
    if (Object.prototype.hasOwnProperty.call(seen, key)) return seen[key];
    if (!withinBudget()) return null;

    const snap = cloneState(s);
    const d = makeDesign(snap);
    let r;
    try {
      r = analyse(d);
      calls++;
    } catch (e) {
      calls++;
      seen[key] = null;
      return null;
    }

    if (!r || r.error) {
      seen[key] = null;
      return null;
    }

    const m = metrics(r, snap);
    const entry = {
      state: snap,
      design: d,
      result: r,
      q: m.q,
      robust: m.robust,
      pass: m.pass,
      mass: m.mass
    };
    seen[key] = entry;

    if (entry.robust &&
        (!bestRobust || entry.mass < bestRobust.mass)) {
      bestRobust = entry;
    }
    if (entry.pass && (!bestPass || entry.mass < bestPass.mass)) {
      bestPass = entry;
    }
    if (!bestNear || entry.q < bestNear.q ||
        (entry.q === bestNear.q && entry.mass < bestNear.mass)) {
      bestNear = entry;
    }
    if (entry.robust &&
        (!bestByKind[s.kind] || entry.mass < bestByKind[s.kind].mass)) {
      bestByKind[s.kind] = entry;
    }
    return entry;
  }

  const seeds = [
    makeState("P", {
      top: "TIMBER190x360",
      bottom: "TIMBER215x540",
      vertical: "TIMBER190x360",
      diagonal: "TIMBER190x450"
    }),
    makeState("P", {
      top: "TIMBER190x450",
      bottom: "TIMBER240x630",
      vertical: "TIMBER190x450",
      diagonal: "TIMBER215x540"
    }),
    makeState("P", {
      top: "TIMBER215x540",
      bottom: "TIMBER280x720",
      vertical: "TIMBER215x540",
      diagonal: "TIMBER280x720"
    }),
    makeState("P", {
      top: "TIMBER320x900",
      bottom: "TIMBER320x900",
      vertical: "TIMBER320x900",
      diagonal: "TIMBER320x900"
    }),
    makeState("W", {
      top: "TIMBER190x450",
      bottom: "TIMBER160x315",
      diagonal: "TIMBER215x540"
    }),
    makeState("W", {
      top: "TIMBER215x540",
      bottom: "TIMBER190x360",
      diagonal: "TIMBER240x630"
    }),
    makeState("W", {
      top: "TIMBER240x630",
      bottom: "TIMBER215x540",
      diagonal: "TIMBER280x720"
    })
  ];

  for (let i = 0; i < seeds.length && withinBudget(); i++) {
    evaluate(seeds[i]);
  }

  function downsize(startEntry, callAllowance) {
    if (!startEntry || !startEntry.robust) return startEntry;

    let current = startEntry;
    let state = cloneState(startEntry.state);
    const stopAt = Math.min(maxCalls, calls + callAllowance);

    for (let pass = 0; pass < 2 && withinBudget() && calls < stopAt; pass++) {
      let changed = false;

      for (let i = 0; i < state.options.length &&
                      withinBudget() && calls < stopAt; i++) {
        let index = state.options[i].index;

        while (index > 0 && withinBudget() && calls < stopAt) {
          const trial = cloneState(state);
          trial.options[i] = timber[index - 1];
          const e = evaluate(trial);

          if (e && e.robust && e.mass < current.mass - 0.1) {
            current = e;
            state = cloneState(e.state);
            index = state.options[i].index;
            changed = true;
          } else {
            break;
          }
        }
      }

      if (!changed) break;
    }
    return current;
  }

  const starts = [];
  if (bestByKind.P) starts.push(bestByKind.P);
  if (bestByKind.W) starts.push(bestByKind.W);
  starts.sort(function(a, b) { return a.mass - b.mass; });

  for (let i = 0; i < starts.length && withinBudget(); i++) {
    downsize(starts[i], 170);
  }

  if (bestRobust) return bestRobust.design;
  if (bestPass) return bestPass.design;
  if (bestNear) return bestNear.design;

  return makeDesign(makeState("P", {
    top: "TIMBER320x900",
    bottom: "TIMBER320x900",
    vertical: "TIMBER320x900",
    diagonal: "TIMBER320x900"
  }));
}

