      for (let i = 0; i < 7; i++) add("D" + i, "D" + (i + 1), "top");
      for (let i = 1; i <= 5; i++) add("B" + i, "B" + (i + 1), "bottom");
      for (let i = 1; i <= 6; i++) add("D" + i, "B" + i, "vertical");
      for (let i = 0; i <= 3; i++) add("D" + i, "B" + (i + 1), "diagonal");
      for (let i = 4; i <= 6; i++) add("B" + i, "D" + (i + 1), "diagonal");
      return edges;
    }

    for (let i = 0; i < 7; i++) add("D" + i, "D" + (i + 1), "top");
    for (let i = 0; i < 6; i++) add("W" + i, "W" + (i + 1), "bottom");
    for (let i = 0; i < 7; i++) {
      add("D" + i, "W" + i, "diagonal");
      add("D" + (i + 1), "W" + i, "diagonal");
    }
    return edges;
  }

  function makeState(kind, roleOptions, placement) {
    const counts = Object.create(null);
    const edges = edgesFor(kind).map(function(e) {
      const i = counts[e.role] || 0;
      counts[e.role] = i + 1;
      const source = roleOptions[e.role];
      const spec = Array.isArray(source) ? source[i] : source;
      return {
        a: e.a,
        b: e.b,
        role: e.role,
        spec: spec
      };
    });
    return {
      kind: kind,
      placement: placement || "global",
      edges: edges
    };
  }

  function cloneState(s) {
    return {
      kind: s.kind,
      placement: s.placement,
      edges: s.edges.map(function(e) {
        return { a: e.a, b: e.b, role: e.role, spec: e.spec };
      })
    };
  }

  function stateKey(s) {
    return s.kind + "|" + s.placement + "|" +
      s.edges.map(function(e) {
        return e.a + ">" + e.b + ":" + e.spec;
      }).join("|");
  }

  function geometry(s) {
    const coords = Object.create(null);
    const degree = Object.create(null);
    const lower = lowerNames(s.kind);

    for (let i = 0; i < 8; i++) {
      coords["D" + i] = { x: xs[i], y: 0 };
    }
    for (let i = 0; i < lower.length; i++) {
      coords[lower[i]] = { x: lowerX(lower[i]), y: -2.44 };
      degree[lower[i]] = 0;
    }
    for (let i = 0; i < s.edges.length; i++) {
      const e = s.edges[i];
      if (degree[e.a] !== undefined) degree[e.a]++;
      if (degree[e.b] !== undefined) degree[e.b]++;
    }

    const active = lower.filter(function(id) {
      return degree[id] > 0;
    });

    if (s.placement === "global") {
      let maxDepth = 180;
      for (let i = 0; i < s.edges.length; i++) {
        const o = optionBySpec[s.edges[i].spec];
        if (o) maxDepth = Math.max(maxDepth, o.depth);
      }
      const y = -2.77 + maxDepth / 2000 + 0.015;
      for (let i = 0; i < lower.length; i++) coords[lower[i]].y = y;
      return { coords: coords, active: active };
    }

    for (let iter = 0; iter < 8; iter++) {
      const nextY = Object.create(null);
      for (let i = 0; i < active.length; i++) {
        const id = active[i];
        let radius = 0;

        for (let j = 0; j < s.edges.length; j++) {
          const e = s.edges[j];
          if (e.a !== id && e.b !== id) continue;

          const other = e.a === id ? e.b : e.a;
          const p = coords[id];
          const q = coords[other];
          const dx = Math.abs(p.x - q.x);
          const dy = p.y - q.y;
          const length = Math.sqrt(dx * dx + dy * dy);
          const o = optionBySpec[e.spec];
          if (o && length > 1e-9) {
            radius = Math.max(radius, (o.depth / 2000) * dx / length);
          }
        }
        nextY[id] = -2.77 + radius + 0.015;
      }

      for (let i = 0; i < active.length; i++) {
        coords[active[i]].y = nextY[active[i]];
      }
    }

    return { coords: coords, active: active };
  }

  function makeDesign(s) {
    const g = geometry(s);
    const nodes = [];

    for (let i = 0; i < g.active.length; i++) {
      const id = g.active[i];
      nodes.push({
        id: id,
        x: g.coords[id].x,
        y: g.coords[id].y,
        joint: "pin"
      });
    }

    const members = s.edges.map(function(e) {
      return [e.a, e.b, e.spec];
    });

    return {
      note: note,
      nodes: nodes,
      joints: {},
      members: members
    };
  }

  function estimatedMass(s) {
    const g = geometry(s);
    let mass = 12 * (8 + g.active.length);

    for (let i = 0; i < s.edges.length; i++) {
      const e = s.edges[i];
      const o = optionBySpec[e.spec];
      if (!o) continue;
      const p = g.coords[e.a];
      const q = g.coords[e.b];
      const dx = p.x - q.x;
      const dy = p.y - q.y;
      const length = Math.sqrt(dx * dx + dy * dy);
      mass += o.linearMass * (length + 0.7);
    }
    return mass;
  }

  function fatigueRatio(x) {
    if (isNum(x)) return x > 2 ? x / 4.678 : x;

    if (Array.isArray(x)) {
      let best = null;
      for (let i = 0; i < x.length; i++) {
        const r = fatigueRatio(x[i]);
        if (isNum(r) && (best === null || r > best)) best = r;
      }
      return best;
    }

    if (!x || typeof x !== "object") return null;

    let util = null;
    let stress = null;
    let limit = null;

    for (const key of Object.keys(x)) {
      const k = key.toLowerCase();
      const value = x[key];
      if (!isNum(value)) continue;

      if (k.includes("util") || k.includes("ratio") ||
          k.includes("unity") || k.includes("usage")) {
        if (util === null || value > util) util = value;
      } else if (k.includes("limit") || k.includes("allow") ||
                 k.includes("capacity")) {
        limit = value;
      } else if (k.includes("stress") || k.includes("range") ||
                 k.includes("delta")) {
        stress = value;
      }
    }

    if (util !== null) return util;
    if (stress !== null && limit !== null && limit > 0) return stress / limit;
    if (stress !== null) return stress / 4.678;

    let best = null;
    for (const key of Object.keys(x)) {
      const r = fatigueRatio(x[key]);
      if (isNum(r) && (best === null || r > best)) best = r;
    }
    return best;
  }

  function metrics(r, s) {
    let uls = isNum(r.maxUtil) ? r.maxUtil : null;

    if (Array.isArray(r.cases)) {
      for (let i = 0; i < r.cases.length; i++) {
        const u = r.cases[i] && r.cases[i].maxUtil;
        if (isNum(u) && (uls === null || u > uls)) uls = u;
      }
    }
    if (uls === null) uls = Infinity;

    let fatigue = fatigueRatio(r.fatigueWorst);
    if (!isNum(fatigue) && Array.isArray(r.members)) {
      fatigue = null;
      for (let i = 0; i < r.members.length; i++) {
        const m = r.members[i];
        if (m && String(m.mode || "").toLowerCase().includes("fatigue") &&
            isNum(m.util)) {
          if (fatigue === null || m.util > fatigue) fatigue = m.util;
        }
      }
    }
    if (!isNum(fatigue)) fatigue = Infinity;

    let sag = isNum(r.sag) ? Math.abs(r.sag) : null;
    if (Array.isArray(r.cases)) {
      for (let i = 0; i < r.cases.length; i++) {
        const v = r.cases[i] && r.cases[i].sag;
        if (isNum(v)) {
          sag = sag === null ? Math.abs(v) : Math.max(sag, Math.abs(v));
        }
      }
    }

    const sagLimit = isNum(r.sagLimit) && r.sagLimit > 0 ? r.sagLimit : 45;
    const sagRatio = sag === null ? Infinity : sag / sagLimit;
    const fMin = isNum(r.fMin) && r.fMin > 0 ? r.fMin : 4.5;
    const frequency = isNum(r.frequency) && r.frequency > 0 ? r.frequency : 0;

    const q = Math.max(
      uls / 0.78,
      fatigue / 0.92,
      sagRatio / 0.80,
      frequency > 0 ? 1.20 * fMin / frequency : Infinity
    );

    let failureText = "";
    if (typeof r.failure === "string") failureText = r.failure.toLowerCase().trim();
    const failureOK = failureText === "" || failureText === "none" ||
      failureText === "ok" || failureText === "pass" ||
      failureText === "passed" || failureText === "no failure";

    return {
      q: q,
      safe: r.ok === true && failureOK && q <= 1,
      mass: isNum(r.mass) ? r.mass : estimatedMass(s)
    };
  }

  const seen = Object.create(null);
  let bestRobust = null;
  let bestNear = null;
  const bestByKind = Object.create(null);
  const bestNearByKind = Object.create(null);

  function evaluate(s) {
    const key = stateKey(s);
    if (Object.prototype.hasOwnProperty.call(seen, key)) return seen[key];
    if (!withinBudget()) return null;

    const snap = cloneState(s);
    const d = makeDesign(snap);
    let r;

    try {
      r = analyse(d);
      calls++;
    } catch (e) {
      calls++;
      seen[key] = null;
      return null;
    }

    if (!r || r.error) {
      seen[key] = null;
      return null;
    }

    const m = metrics(r, snap);
    const entry = {
      state: snap,
      design: d,
      result: r,
      q: m.q,
      safe: m.safe,
      mass: m.mass
    };
    seen[key] = entry;

    if (entry.safe &&
        (!bestRobust || entry.mass < bestRobust.mass)) {
      bestRobust = entry;
    }

    if (!bestNear || entry.q < bestNear.q ||
        (entry.q === bestNear.q && entry.mass < bestNear.mass)) {
      bestNear = entry;
    }

    if (!bestNearByKind[s.kind] ||
        entry.q < bestNearByKind[s.kind].q ||
        (entry.q === bestNearByKind[s.kind].q &&
         entry.mass < bestNearByKind[s.kind].mass)) {
      bestNearByKind[s.kind] = entry;
    }

    if (entry.safe &&
        (!bestByKind[s.kind] || entry.mass < bestByKind[s.kind].mass)) {
      bestByKind[s.kind] = entry;
    }
    return entry;
  }

  function repair(entry, allowance) {
    if (!entry || entry.safe) return entry;

    let current = entry;
    const stopAt = Math.min(maxCalls, calls + allowance);

    for (let step = 0; step < 2 && withinBudget() && calls < stopAt; step++) {
      let winner = null;

      for (let i = 0; i < current.state.edges.length &&
                      withinBudget() && calls < stopAt; i++) {
        const oldSpec = current.state.edges[i].spec;
        const idx = timberIndexBySpec[oldSpec];
        if (typeof idx !== "number" || idx >= timberOptions.length - 1) continue;

        const trial = cloneState(current.state);
        trial.edges[i].spec = timberOptions[idx + 1].spec;
        const e = evaluate(trial);

        if (e && (!winner || e.q < winner.q ||
                  (e.q === winner.q && e.mass < winner.mass))) {
          winner = e;
        }
      }

      if (!winner) break;
      if (winner.safe || winner.q < current.q - 1e-5) {
        current = winner;
      } else {
        break;
      }
      if (current.safe) break;
    }
    return current;
  }

  function shrink(entry, allowance) {
    if (!entry || !entry.safe) return entry;

    let current = entry;
    const stopAt = Math.min(maxCalls, calls + allowance);

    for (let pass = 0; pass < 2 && withinBudget() && calls < stopAt; pass++) {
      const g = geometry(current.state);
      const order = [];

      for (let i = 0; i < current.state.edges.length; i++) {
        const e = current.state.edges[i];
        const o = optionBySpec[e.spec];
        const p = g.coords[e.a];
        const q = g.coords[e.b];
        const dx = p.x - q.x;
        const dy = p.y - q.y;
        const length = Math.sqrt(dx * dx + dy * dy);
        order.push({
          index: i,
          weight: o ? o.linearMass * (length + 0.7) : 0
        });
      }
      order.sort(function(a, b) {
        return b.weight - a.weight;
      });

      let changed = false;
      for (let oi = 0; oi < order.length &&
                       withinBudget() && calls < stopAt; oi++) {
        const edgeIndex = order[oi].index;
        let idx = timberIndexBySpec[current.state.edges[edgeIndex].spec];

        while (typeof idx === "number" && idx > 0 &&
               withinBudget() && calls < stopAt) {
          const trial = cloneState(current.state);
          trial.edges[edgeIndex].spec = timberOptions[idx - 1].spec;
          const e = evaluate(trial);

          if (e && e.safe && e.mass < current.mass - 0.05) {
            current = e;
            idx = timberIndexBySpec[current.state.edges[edgeIndex].spec];
            changed = true;
          } else {
            break;
          }
        }
      }

      if (!changed) break;
    }
    return current;
  }

  function uniformRoles(top, bottom, vertical, diagonal) {
    return {
      top: top,
      bottom: bottom,
      vertical: vertical,
      diagonal: diagonal
    };
  }

  const fullRoles = {
    top: [
      "GL28 TIMBER160x315",
      "GL28 TIMBER160x315",
      "GL28 TIMBER160x315",
      "GL28 TIMBER190x360",
      "GL28 TIMBER190x450",
      "GL28 TIMBER190x450",
      "GL28 TIMBER190x360"
    ],
    bottom: [
      "GL28 TIMBER90x180",
      "GL28 TIMBER190x360",
      "GL28 TIMBER215x540",
      "GL28 TIMBER240x630",
      "GL28 TIMBER215x540",
      "GL28 TIMBER190x360",
      "GL28 TIMBER90x180"
    ],
    vertical: [
      "GL28 TIMBER90x180",
      "GL28 TIMBER190x360",
      "GL28 TIMBER160x315",
      "GL28 TIMBER160x315",
      "GL28 TIMBER140x270",
      "GL28 TIMBER160x315",
      "GL28 TIMBER190x360",
      "GL28 TIMBER90x180"
    ],
    diagonal: [
      "GL28 TIMBER190x450",
      "GL28 TIMBER190x360",
      "GL28 TIMBER190x360",
      "GL28 TIMBER190x360",
      "GL28 TIMBER190x360",
      "GL28 TIMBER190x360",
      "GL28 TIMBER190x450"
    ]
  };

  const p6Roles = {
    top: fullRoles.top.slice(),
    bottom: fullRoles.bottom.slice(1, 6),
    vertical: fullRoles.vertical.slice(1, 7),
    diagonal: fullRoles.diagonal.slice()
  };

  const seeds = [
    makeState("P", fullRoles, "global"),
    makeState("P", fullRoles, "local"),
    makeState("P6", p6Roles, "global"),
    makeState("P6", p6Roles, "local"),
    makeState("W", uniformRoles(
      "GL28 TIMBER190x450",
      "GL28 TIMBER160x315",
      "",
      "GL28 TIMBER215x540"
    ), "global"),
    makeState("W", uniformRoles(
      "GL28 TIMBER190x450",
      "GL28 TIMBER160x315",
      "",
      "GL28 TIMBER215x540"
    ), "local"),
    makeState("W", uniformRoles(
      "GL28 TIMBER215x540",
      "GL28 TIMBER190x360",
      "",
      "GL28 TIMBER240x630"
    ), "global"),
    makeState("W", uniformRoles(
      "GL28 TIMBER160x315",
      "GL28 TIMBER90x180",
      "",
      "GL28 TIMBER190x360"
    ), "global")
  ];

  for (let i = 0; i < seeds.length && withinBudget(); i++) {
    evaluate(seeds[i]);
  }

  if (!bestByKind.P6 && bestNearByKind.P6 && withinBudget()) {
    repair(bestNearByKind.P6, 28);
  }
  if (!bestByKind.W && bestNearByKind.W && withinBudget()) {
    repair(bestNearByKind.W, 20);
  }

  let p6Start = bestByKind.P6;
  let pStart = bestByKind.P;
  let wStart = bestByKind.W;

  if (p6Start && withinBudget()) shrink(p6Start, 100);
  if (pStart && withinBudget()) shrink(pStart, 34);
  if (wStart && withinBudget()) shrink(wStart, 50);

  const representatives = [];
  if (bestByKind.P6) representatives.push(bestByKind.P6);
  if (bestByKind.P) representatives.push(bestByKind.P);
  if (bestByKind.W) representatives.push(bestByKind.W);

  let bestDeleted = null;
  let bestNearDeleted = null;

  for (let ri = 0; ri < representatives.length && withinBudget(); ri++) {
    const rep = representatives[ri];

    for (let i = 0; i < rep.state.edges.length && withinBudget(); i++) {
      const trial = cloneState(rep.state);
      trial.edges.splice(i, 1);
      const e = evaluate(trial);
      if (!e) continue;

      if (e.safe) {
        if (!bestDeleted || e.mass < bestDeleted.mass) bestDeleted = e;
      } else if (e.q < 1.18 &&
                 (!bestNearDeleted || e.q < bestNearDeleted.q ||
                  (e.q === bestNearDeleted.q &&
                   e.mass < bestNearDeleted.mass))) {
        bestNearDeleted = e;
      }
    }
  }

  if (bestDeleted && withinBudget()) {
    shrink(bestDeleted, 64);
  } else if (bestNearDeleted && withinBudget()) {
    const repaired = repair(bestNearDeleted, 28);
    if (repaired && repaired.safe && withinBudget()) shrink(repaired, 28);
  }

  function normalizeMemberId(id) {
    let s = String(id || "")
      .replace(/[–—]/g, "-")
      .replace(/\s*\([^)]*\)\s*$/, "");
    const parts = s.split("-");
    if (parts.length !== 2) return s;
    parts.sort();
    return parts[0] + "|" + parts[1];
  }

  function memberInfo(entry, edge) {
    const list = entry && entry.result && entry.result.members;
    if (!Array.isArray(list)) return null;

    const target = normalizeMemberId(edge.a + "-" + edge.b);
    for (let i = 0; i < list.length; i++) {
      const m = list[i];
      if (!m) continue;
      let id = m.id || m.member || "";
      if (!id && m.a && m.b) id = m.a + "-" + m.b;
      if (normalizeMemberId(id) === target) return m;
    }
    return null;
  }

  function materialSearch(entry, allowance) {
    if (!entry || !entry.safe) return entry;

    let current = entry;
    const stopAt = Math.min(maxCalls, calls + allowance);

    for (let i = 0; i < current.state.edges.length &&
                    withinBudget() && calls < stopAt; i++) {
      const edge = current.state.edges[i];
      const old = optionBySpec[edge.spec];
      if (!old || old.material !== "GL28") continue;

      const info = memberInfo(current, edge);
      if (!info || !isNum(info.util) || info.util >= 0.58) continue;

      const mode = String(info.mode || "").toLowerCase();
      const fatigueMode = mode.includes("fatigue");
      const compression = isNum(info.compression) ? info.compression : Infinity;
      const candidates = [];
      const materials = ["AL6082", "S690", "WIRE"];

      for (let mi = 0; mi < materials.length; mi++) {
        const mat = materials[mi];
        if (mat === "WIRE" &&
            (!fatigueMode || compression > 0.1)) continue;

        const list = altByMaterial[mat] || [];
        const newFatigue = mat === "WIRE" ? 110 :
                           mat === "AL6082" ? 32 : 90;
        const newFy = mat === "WIRE" ? 714 :
                      mat === "AL6082" ? 260 : 690;

        let targetArea;
        if (fatigueMode) {
          targetArea = old.area * (info.util / 0.92) *
            (8 / newFatigue) * 1.10;
        } else {
          if (!mode.includes("buckl") &&
              !mode.includes("tension") &&
              !mode.includes("compression")) continue;
          const buckling = mode.includes("buckl") || compression > 0;
          targetArea = old.area * (info.util / 0.78) *
            (17.6 / newFy) * (buckling ? 2.5 : 1.3);
        }

        const eligible = list.filter(function(o) {
          return o.area >= targetArea &&
                 o.linearMass < old.linearMass * 0.97;
        }).sort(function(a, b) {
          return a.linearMass - b.linearMass;
        });

        for (let j = 0; j < eligible.length && j < 2; j++) {
          candidates.push(eligible[j]);
        }
      }

      candidates.sort(function(a, b) {
        return a.linearMass - b.linearMass;
      });

      for (let j = 0; j < candidates.length && j < 5 &&
                      withinBudget() && calls < stopAt; j++) {
        const trial = cloneState(current.state);
        trial.edges[i].spec = candidates[j].spec;
        const e = evaluate(trial);
        if (e && e.safe && e.mass < current.mass - 0.05) {
          current = e;
          break;
        }
      }
    }
    return current;
  }

  if (bestRobust && withinBudget()) {
    materialSearch(bestRobust, Math.min(50, maxCalls - calls));
  }

  if (bestRobust) return bestRobust.design;

  return makeDesign(makeState("P", fullRoles, "global"));
}

function design(site, analyse) {
  const started = Date.now();
  const maxCalls = 390;
  const maxMillis = 87000;
  let calls = 0;

  const note =
    "A pinned GL28 P6 truss uses locally deepened lower nodes and a robust search over node spacing and member sizes.";
  const deckX = [0, 2.571, 5.143, 7.714, 10.286, 12.857, 15.429, 18];

  const sectionRows = [
    ["TIMBER90x180", 162, 180],
    ["TIMBER115x225", 258.75, 225],
    ["TIMBER140x270", 378, 270],
    ["TIMBER160x315", 504, 315],
    ["TIMBER190x360", 684, 360],
    ["TIMBER190x450", 855, 450],
    ["TIMBER215x540", 1161, 540],
    ["TIMBER240x630", 1512, 630],
    ["TIMBER280x720", 2016, 720],
    ["TIMBER320x900", 2880, 900]
  ];

  const sections = sectionRows.map(function(row) {
    return {
      id: row[0],
      spec: "GL28 " + row[0],
      area: row[1],
      depth: row[2],
      density: 420,
      linearMass: 420 * row[1] / 10000
    };
  });

  function isNum(x) {
    return typeof x === "number" && isFinite(x);
  }

  function withinBudget() {
    return calls < maxCalls && Date.now() - started < maxMillis;
  }

  function baseState(x, placement) {
    const edges = [];

    function add(a, b, oi, role) {
      edges.push({ a: a, b: b, oi: oi, role: role });
    }

    const topSizes = [3, 3, 3, 4, 5, 5, 4];
    for (let i = 0; i < 7; i++) {
      add("D" + i, "D" + (i + 1), topSizes[i], "top");
    }

    const bottomSizes = [4, 6, 7, 6, 4];
    for (let i = 1; i <= 5; i++) {
      add("B" + i, "B" + (i + 1), bottomSizes[i - 1], "bottom");
    }

    const verticalSizes = [4, 3, 3, 2, 3, 4];
    for (let i = 1; i <= 6; i++) {
      add("D" + i, "B" + i, verticalSizes[i - 1], "vertical");
    }

    const diagonalEnds = [
      ["D0", "B1", 5],
      ["D1", "B2", 4],
      ["D2", "B3", 4],
      ["D3", "B4", 4],
      ["B4", "D5", 4],
      ["B5", "D6", 4],
      ["B6", "D7", 5]
    ];
    for (let i = 0; i < diagonalEnds.length; i++) {
      add(diagonalEnds[i][0], diagonalEnds[i][1],
          diagonalEnds[i][2], "diagonal");
    }

    return {
      kind: "P6",
      x: x.slice(),
      placement: placement,
      edges: edges
    };
  }

