    if (!withinBudget()) return null;

    const snap = cloneState(s);
    const d = makeDesign(snap);
    if (!d) {
      seen[key] = null;
      return null;
    }

    let r;
    try {
      r = analyse(d);
      calls++;
    } catch (e) {
      calls++;
      seen[key] = null;
      return null;
    }

    if (!r || r.error) {
      seen[key] = null;
      return null;
    }

    const m = metrics(r, snap);
    const entry = {
      state: snap,
      design: d,
      result: r,
      q: m.q,
      safe: m.safe,
      mass: m.mass
    };
    seen[key] = entry;

    if (entry.safe &&
        (!best || entry.mass < best.mass - 0.01)) {
      best = entry;
    }

