        const e = current.state.edges[i];
        if (e.oi <= 0) continue;

        const p = g.coords[e.a];
        const q = g.coords[e.b];
        const dx = p.x - q.x;
        const dy = p.y - q.y;
        const length = Math.sqrt(dx * dx + dy * dy);
        const saving =
          (sections[e.oi].linearMass -
           sections[e.oi - 1].linearMass) * (length + 0.7);
