    const stopAt = Math.min(MAX_CALLS, calls + allowance);

    for (let pass = 0; pass < 2 && withinBudget() &&
                        calls < stopAt; pass++) {
      let winner = null;

      for (let i = 0; i < current.state.edges.length &&
                      withinBudget() && calls < stopAt; i++) {
        const old = current.state.edges[i].oi;
        if (old >= sections.length - 1) continue;

        const trial = cloneState(current.state);
        trial.edges[i].oi++;
