      }
    }
    return util === null ? 1 : util;
  }

  function deleteCandidates(entry) {
    const found = [];
    if (!entry || !entry.safe) return found;

    const g = geometry(entry.state);
    const order = [];
    for (let i = 0; i < entry.state.edges.length; i++) {
      const e = entry.state.edges[i];
      const p = g.coords[e.a];
      const q = g.coords[e.b];
      const dx = p.x - q.x;
      const dy = p.y - q.y;
      const length = Math.sqrt(dx * dx + dy * dy);
      const contribution = sections[e.oi].linearMass * (length + 0.7);
      const util = memberUtil(entry, e);
      order.push({
        index: i,
        priority: contribution / (0.25 + Math.max(0, util))
      });
    }
    order.sort(function(a, b) {
      return b.priority - a.priority;
    });

    for (let j = 0; j < order.length && withinBudget(); j++) {
      const trial = cloneState(entry.state);
      trial.edges.splice(order[j].index, 1);
      const e = evaluate(trial);
      if (e && e.safe && e.mass < entry.mass - 0.05) {
        found.push(e);
      }
    }

    found.sort(function(a, b) {
      return a.mass - b.mass || a.q - b.q;
    });
    return found;
  }

  const seedStates = [makeP6(), makeP5(), makeP4()];
  const seedEntries = [];

  for (let i = 0; i < seedStates.length && withinBudget(); i++) {
    seedEntries.push(evaluate(seedStates[i]));
  }

  for (let i = 0; i < seedEntries.length && withinBudget(); i++) {
    const e = seedEntries[i];
    if (e && !e.safe && e.q < 1.35) {
      repair(e, 18);
    }
  }

  let roots = Object.keys(bestByFamily).map(function(k) {
    return bestByFamily[k];
  });
  roots.sort(function(a, b) {
    return a.mass - b.mass;
  });

  const optimizedRoots = [];
  for (let i = 0; i < roots.length && withinBudget(); i++) {
    const entry = improveSections(roots[i], 44);
    if (entry && entry.safe) optimizedRoots.push(entry);
  }

  const deletionMap = Object.create(null);
  for (let i = 0; i < optimizedRoots.length && withinBudget(); i++) {
    const candidates = deleteCandidates(optimizedRoots[i]);
    for (let j = 0; j < candidates.length; j++) {
      deletionMap[stateKey(candidates[j].state)] = candidates[j];
    }
  }

  let deletions = Object.keys(deletionMap).map(function(k) {
    return deletionMap[k];
  });
  deletions.sort(function(a, b) {
    return a.mass - b.mass || a.q - b.q;
  });

  for (let i = 0; i < deletions.length && i < 3 && withinBudget(); i++) {
    const allowance = Math.min(36, MAX_CALLS - calls);
    if (allowance > 0) improveSections(deletions[i], allowance);
  }

  const originalCounts = { P6: 25, P5: 23, P4: 21 };
  for (let pass = 0; pass < 2 && best && withinBudget(); pass++) {
    const count = originalCounts[best.state.family];
    if (count === undefined || best.state.edges.length >= count) break;

    const next = deleteCandidates(best);
    if (!next.length) break;
    const allowance = Math.min(32, MAX_CALLS - calls);
    if (allowance > 0) improveSections(next[0], allowance);
  }

  if (best && withinBudget() && calls < MAX_CALLS - 2) {
    for (const factor of [0.98, 1.02]) {
      if (!withinBudget() || calls >= MAX_CALLS - 2) break;
      const trial = cloneState(best.state);
      trial.lower = trial.lower.map(function(n) {
        return { id: n.id, x: 9 + (n.x - 9) * factor };
      });
      evaluate(trial);
    }

    if (best && withinBudget()) {
      improveSections(best, Math.min(20, MAX_CALLS - calls));
    }
  }

  if (best) return best.design;
  return makeDesign(makeP6());
}

