        nodes.push({
          id: id,
          x: coords[id].x,
          y: coords[id].y,
          joint: "pin"
        });
      }
    }

    return {
      note: note,
      nodes: nodes,
      joints: {},
      members: members
    };
  }

  function estimatedMass(s) {
    const coords = geometry(s);
    const used = Object.create(null);
    for (let i = 0; i < s.edges.length; i++) {
      used[s.edges[i].a] = true;
      used[s.edges[i].b] = true;
    }

    let mass = 12 * Object.keys(used).length;
    for (let i = 0; i < s.edges.length; i++) {
      const e = s.edges[i];
      const p = coords[e.a];
      const q = coords[e.b];
      const dx = p.x - q.x;
      const dy = p.y - q.y;
      const length = Math.sqrt(dx * dx + dy * dy);
      mass += gl[e.gi].linearMass * (length + 0.7);
    }
    return mass;
  }

  function fatigueRatio(x) {
    if (isNum(x)) return x > 2 ? x / 4.678 : x;

    if (Array.isArray(x)) {
      let best = null;
      for (let i = 0; i < x.length; i++) {
        const r = fatigueRatio(x[i]);
        if (isNum(r) && (best === null || r > best)) best = r;
      }
      return best;
    }

    if (!x || typeof x !== "object") return null;

    let util = null;
    let stress = null;
    let limit = null;
    for (const key of Object.keys(x)) {
      const k = key.toLowerCase();
      const value = x[key];
      if (!isNum(value)) continue;

      if (k.includes("util") || k.includes("ratio") ||
          k.includes("unity") || k.includes("usage")) {
        util = util === null ? value : Math.max(util, value);
      } else if (k.includes("limit") || k.includes("allow") ||
                 k.includes("capacity")) {
        limit = value;
      } else if (k.includes("stress") || k.includes("range") ||
                 k.includes("delta")) {
        stress = value;
      }
    }

    if (util !== null) return util;
    if (stress !== null && limit !== null && limit > 0) return stress / limit;
    if (stress !== null) return stress / 4.678;

    let best = null;
    for (const key of Object.keys(x)) {
      const r = fatigueRatio(x[key]);
      if (isNum(r) && (best === null || r > best)) best = r;
    }
    return best;
  }

  function metrics(r) {
    let uls = isNum(r.maxUtil) ? r.maxUtil : null;
    if (Array.isArray(r.cases)) {
      for (let i = 0; i < r.cases.length; i++) {
        const u = r.cases[i] && r.cases[i].maxUtil;
        if (isNum(u) && (uls === null || u > uls)) uls = u;
      }
    }
    if (uls === null) uls = Infinity;

    let fatigue = fatigueRatio(r.fatigueWorst);
    if (!isNum(fatigue) && Array.isArray(r.members)) {
      fatigue = null;
      for (let i = 0; i < r.members.length; i++) {
        const m = r.members[i];
        if (m && String(m.mode || "").toLowerCase().includes("fatigue") &&
            isNum(m.util)) {
          fatigue = fatigue === null ? m.util : Math.max(fatigue, m.util);
        }
      }
    }
    if (!isNum(fatigue)) fatigue = Infinity;

    let sag = isNum(r.sag) ? Math.abs(r.sag) : null;
    if (Array.isArray(r.cases)) {
      for (let i = 0; i < r.cases.length; i++) {
        const v = r.cases[i] && r.cases[i].sag;
        if (isNum(v)) sag = sag === null ? Math.abs(v) :
          Math.max(sag, Math.abs(v));
      }
    }
    if (sag === null) sag = Infinity;

    const frequency = isNum(r.frequency) && r.frequency > 0 ?
      r.frequency : 0;
    const q = Math.max(
      uls / 0.75,
      fatigue / 0.92,
      sag / 36,
      frequency > 0 ? 5.4 / frequency : Infinity
    );

    let failure = "";
    if (typeof r.failure === "string") failure = r.failure.toLowerCase().trim();
    const failureOK = failure === "" || failure === "none" ||
      failure === "ok" || failure === "pass" || failure === "passed" ||
      failure === "no failure";

    return {
      q: q,
      pass: r.ok === true && failureOK,
      safe: r.ok === true && failureOK && q <= 1,
      mass: isNum(r.mass) ? r.mass : null
    };
  }

  const seen = Object.create(null);
  const bestByFamily = Object.create(null);
  let best = null;
  let bestPass = null;

  function evaluate(s) {
    const key = stateKey(s);
    if (Object.prototype.hasOwnProperty.call(seen, key)) return seen[key];
    if (!withinBudget()) return null;

    const snap = cloneState(s);
    const d = makeDesign(snap);
    if (!d) {
      seen[key] = null;
      return null;
    }

    let r;
    try {
      r = analyse(d);
      calls++;
    } catch (e) {
      calls++;
      seen[key] = null;
      return null;
    }

    if (!r || r.error) {
      seen[key] = null;
      return null;
    }

    const m = metrics(r);
    const mass = m.mass === null ? estimatedMass(snap) : m.mass;
    const entry = {
      state: snap,
      design: d,
      result: r,
      q: m.q,
      safe: m.safe,
      pass: m.pass,
      mass: mass
    };
    seen[key] = entry;

    if (entry.safe &&
        (!best || entry.mass < best.mass - 0.01 ||
         (Math.abs(entry.mass - best.mass) < 0.01 && entry.q < best.q))) {
      best = entry;
    }
    if (entry.pass &&
        (!bestPass || entry.mass < bestPass.mass - 0.01)) {
      bestPass = entry;
    }

    const old = bestByFamily[snap.family];
    if (entry.safe &&
        (!old || entry.mass < old.mass - 0.01)) {
      bestByFamily[snap.family] = entry;
    }
    return entry;
  }

  function normalizedMemberId(id) {
    const text = String(id || "")
      .replace(/[–—]/g, "-")
      .replace(/\s*\([^)]*\)\s*$/, "");
    const parts = text.split("-");
    if (parts.length !== 2) return text;
    parts.sort();
    return parts[0] + "|" + parts[1];
  }

  function memberUtil(entry, edge) {
    const list = entry.result && entry.result.members;
    if (!Array.isArray(list)) return 1;

    const target = normalizedMemberId(edge.a + "-" + edge.b);
    let util = null;
    for (let i = 0; i < list.length; i++) {
      const m = list[i];
      if (!m) continue;
      let id = m.id || m.member || "";
      if (!id && m.a && m.b) id = m.a + "-" + m.b;
      if (normalizedMemberId(id) === target && isNum(m.util)) {
        util = util === null ? m.util : Math.max(util, m.util);
      }
    }
    return util === null ? 1 : util;
  }

  function repair(entry, allowance) {
    if (!entry || entry.safe || !isNum(entry.q)) return entry;

    let current = entry;
    const stopAt = Math.min(MAX_CALLS, calls + allowance);

    for (let pass = 0; pass < 3 && withinBudget() && calls < stopAt; pass++) {
      const order = [];
      for (let i = 0; i < current.state.edges.length; i++) {
        const e = current.state.edges[i];
        if (e.gi < gl.length - 1) {
          order.push({ index: i, util: memberUtil(current, e) });
        }
      }
      order.sort(function(a, b) { return b.util - a.util; });

      let winner = null;
      for (let j = 0; j < order.length && j < 12 &&
                      withinBudget() && calls < stopAt; j++) {
        const trial = cloneState(current.state);
        const k = order[j].index;
        trial.edges[k].gi++;
        const e = evaluate(trial);
        if (!e) continue;

        if (e.safe) {
          if (!winner || !winner.safe || e.mass < winner.mass) winner = e;
        } else if ((!winner || !winner.safe) && e.q < current.q - 1e-5 &&
                   (!winner || e.q < winner.q)) {
          winner = e;
        }
      }

      if (!winner) break;
      current = winner;
      if (current.safe) break;
    }
    return current;
  }

  function downsize(entry, allowance) {
    if (!entry || !entry.safe) return entry;

    let current = entry;
    const stopAt = Math.min(MAX_CALLS, calls + allowance);

    for (let pass = 0; pass < 4 && withinBudget() && calls < stopAt; pass++) {
      const coords = geometry(current.state);
      const order = [];

      for (let i = 0; i < current.state.edges.length; i++) {
        const e = current.state.edges[i];
        if (e.gi <= 0) continue;
        const p = coords[e.a];
        const q = coords[e.b];
        const dx = p.x - q.x;
        const dy = p.y - q.y;
        const length = Math.sqrt(dx * dx + dy * dy);
        const saving =
          (gl[e.gi].linearMass - gl[e.gi - 1].linearMass) *
          (length + 0.7);
        order.push({ index: i, saving: saving });
      }
      order.sort(function(a, b) { return b.saving - a.saving; });

      let winner = null;
      for (let j = 0; j < order.length &&
                      withinBudget() && calls < stopAt; j++) {
        const trial = cloneState(current.state);
        trial.edges[order[j].index].gi--;
        const e = evaluate(trial);
        if (e && e.safe && e.mass < current.mass - 0.03 &&
            (!winner || e.mass < winner.mass)) {
          winner = e;
        }
      }

      if (!winner) break;
      current = winner;
    }
    return current;
  }

  const x0 = deckX.slice(1, 7);
  function scaledX(factor) {
    return x0.map(function(v) { return 9 + (v - 9) * factor; });
  }

  const seedStates = [
    makeP6(x0, 0.015),
    makeP6(x0, 0.010),
    makeP6(x0, 0.008)
  ];

  [0.88, 0.92, 0.96, 0.98, 1.02, 1.04, 1.08, 1.12, 1.16].forEach(
    function(f) { seedStates.push(makeP6(scaledX(f), 0.010)); }
  );

  seedStates.push(makeP6(
    [1.571, 5.143, 7.714, 10.286, 12.857, 16.429], 0.010
  ));

  let xx = x0.slice();
  xx[0] -= 0.25;
  xx[5] += 0.25;
  seedStates.push(makeP6(xx, 0.010));

  xx = x0.slice();
  xx[0] += 0.25;
  xx[5] -= 0.25;
  seedStates.push(makeP6(xx, 0.010));

  seedStates.push(makeP5());
  seedStates.push(makeP4());

  seedStates.push(makeCable(5.143, 1.75, 12.4, 1.30));
  seedStates.push(makeCable(5.143, 1.72, 12.4, 1.30));
  seedStates.push(makeCable(5.10, 1.80, 12.4, 1.30));
  seedStates.push(makeCable(5.143, 1.75, 12.4, 1.32));

  const seedEntries = [];
  for (let i = 0; i < seedStates.length && withinBudget(); i++) {
    const e = evaluate(seedStates[i]);
    if (e) seedEntries.push(e);
  }

  const failedSeeds = seedEntries.filter(function(e) {
    return !e.safe && isNum(e.q) && e.q < 1.40;
  }).sort(function(a, b) {
    return a.q - b.q;
  });

  for (let i = 0; i < failedSeeds.length && i < 3 && withinBudget(); i++) {
    repair(failedSeeds[i], 16);
  }

  const rootList = [];
  const rootShapes = Object.create(null);

  function shapeKey(s) {
    return s.family + "|" +
      s.lower.map(function(n) {
        return n.id + "@" + n.x.toFixed(3);
      }).join(",") + "|" +
      s.extra.map(function(n) {
        return n.id + "@" + n.x.toFixed(3) + "," + n.y.toFixed(3);
      }).join(",");
  }

  function addRoot(e) {
    if (!e || !e.safe || rootList.length >= 5) return;
    const k = shapeKey(e.state);
    if (rootShapes[k]) return;
    rootShapes[k] = true;
    rootList.push(e);
  }

  const familyRoots = Object.keys(bestByFamily).map(function(k) {
    return bestByFamily[k];
  }).sort(function(a, b) { return a.mass - b.mass; });

  for (let i = 0; i < familyRoots.length && rootList.length < 5; i++) {
    addRoot(familyRoots[i]);
  }

  seedEntries.filter(function(e) { return e.safe; })
    .sort(function(a, b) { return a.mass - b.mass; })
    .forEach(function(e) { addRoot(e); });

  for (let i = 0; i < rootList.length && withinBudget(); i++) {
    const allowance = Math.min(36, MAX_CALLS - calls - 8);
    if (allowance > 0) downsize(rootList[i], allowance);
  }

  const p6Source = bestByFamily.P6;
  if (p6Source && p6Source.safe && withinBudget()) {
    const coords = geometry(p6Source.state);
    const order = [];

    for (let i = 0; i < p6Source.state.edges.length; i++) {
      const e = p6Source.state.edges[i];
      const p = coords[e.a];
      const q = coords[e.b];
      const length = Math.sqrt(
        (p.x - q.x) * (p.x - q.x) + (p.y - q.y) * (p.y - q.y)
      );
      const contribution = gl[e.gi].linearMass * (length + 0.7);
      const util = memberUtil(p6Source, e);
      order.push({
        index: i,
        priority: contribution / (0.30 + Math.max(0.05, util))
      });
    }
    order.sort(function(a, b) { return b.priority - a.priority; });

    const deletions = [];
    const repairList = [];
    for (let j = 0; j < order.length && withinBudget(); j++) {
      const trial = cloneState(p6Source.state);
      trial.edges.splice(order[j].index, 1);
      const e = evaluate(trial);
      if (e && e.safe) {
        deletions.push(e);
      } else if (e && isNum(e.q) && e.q < 1.30) {
        repairList.push({ entry: e, priority: order[j].priority });
      }
    }

    repairList.sort(function(a, b) { return b.priority - a.priority; });
    for (let i = 0; i < repairList.length && i < 3 && withinBudget(); i++) {
      const allowance = Math.min(11, MAX_CALLS - calls - 6);
      if (allowance > 0) repair(repairList[i].entry, allowance);
    }

    deletions.sort(function(a, b) {
      return a.mass - b.mass || a.q - b.q;
    });
    for (let i = 0; i < deletions.length && i < 2 && withinBudget(); i++) {
      const allowance = Math.min(20, MAX_CALLS - calls - 5);
      if (allowance > 0) downsize(deletions[i], allowance);
    }
  }

  function refineP6(entry, allowance) {
    if (!entry || !entry.safe || entry.state.lower.length !== 6) return;
    const source = cloneState(entry.state);
    const base = source.lower.map(function(n) { return n.x; });
    const variants = [];

    [0.90, 0.95, 1.05, 1.10].forEach(function(f) {
      variants.push(base.map(function(v) { return 9 + (v - 9) * f; }));
    });

    [
      [0, 5],
      [1, 4],
      [2, 3]
    ].forEach(function(pair) {
      [-0.25, 0.25].forEach(function(d) {
        const v = base.slice();
        v[pair[0]] += d;
        v[pair[1]] -= d;
        variants.push(v);
      });
    });

    const candidates = [];
    const stopAt = Math.min(MAX_CALLS, calls + allowance);
    for (let i = 0; i < variants.length &&
                    withinBudget() && calls < stopAt; i++) {
      const trial = cloneState(source);
      for (let j = 0; j < 6; j++) trial.lower[j].x = variants[i][j];
      const e = evaluate(trial);
      if (e && e.safe) candidates.push(e);
    }

    candidates.sort(function(a, b) {
      return a.mass - b.mass || a.q - b.q;
    });
    if (candidates.length > 0 && withinBudget() && calls < stopAt) {
      downsize(candidates[0], Math.min(22, stopAt - calls));
    }
  }

  if (bestByFamily.P6 && withinBudget()) {
    refineP6(bestByFamily.P6, Math.min(14, MAX_CALLS - calls - 12));
  }

  function refineCable(entry, allowance) {
    if (!entry || !entry.safe || entry.state.family !== "CABLE") return;

    const variants = [];
    const source = cloneState(entry.state);

    function addVariant(change) {
      const t = cloneState(source);
      change(t.extra);
      variants.push(t);
    }

    addVariant(function(n) { n[0].y += 0.02; });
    addVariant(function(n) { n[1].y += 0.02; });
    addVariant(function(n) { n[1].x -= 0.05; });
    addVariant(function(n) {
      n[0].y += 0.02;
      n[1].y += 0.02;
    });

    const candidates = [];
    const stopAt = Math.min(MAX_CALLS, calls + allowance);
    for (let i = 0; i < variants.length &&
                    withinBudget() && calls < stopAt; i++) {
      const e = evaluate(variants[i]);
      if (e && e.safe) candidates.push(e);
    }

    candidates.sort(function(a, b) {
      return a.mass - b.mass || a.q - b.q;
    });
    if (candidates.length > 0 && withinBudget() && calls < stopAt) {
      downsize(candidates[0], Math.min(16, stopAt - calls));
    }
  }

  if (bestByFamily.CABLE && withinBudget()) {
    refineCable(bestByFamily.CABLE, Math.min(20, MAX_CALLS - calls - 5));
  }

  if (best) return best.design;
  if (bestPass) return bestPass.design;
  return makeDesign(makeP6(x0, 0.015));
}

function design(site, analyse) {
  const started = Date.now();
  const MAX_CALLS = 390;
  const MAX_MILLIS = 85000;
  let calls = 0;

  const note =
    "Searches pinned under-deck glulam trusses with two-, three-, and seven-node layouts and alternate triangulations, retaining conservative check margins.";

  const deckX = [0, 2.571, 5.143, 7.714, 10.286, 12.857, 15.429, 18];
  const rawSections = [
    ["TIMBER90x180", 162, 180],
    ["TIMBER115x225", 258.75, 225],
    ["TIMBER140x270", 378, 270],
    ["TIMBER160x315", 504, 315],
    ["TIMBER190x360", 684, 360],
    ["TIMBER190x450", 855, 450],
    ["TIMBER215x540", 1161, 540],
    ["TIMBER240x630", 1512, 630],
    ["TIMBER280x720", 2016, 720],
    ["TIMBER320x900", 2880, 900]
  ];

  const sections = rawSections.map(function(r) {
    return {
      spec: "GL28 " + r[0],
      area: r[1],
      depth: r[2],
      linearMass: 420 * r[1] / 10000
    };
  });

  function isNum(x) {
    return typeof x === "number" && isFinite(x);
  }

  function withinBudget() {
    return calls < MAX_CALLS && Date.now() - started < MAX_MILLIS;
  }

  function edgeKey(a, b) {
    const p = [a, b];
    p.sort();
    return p[0] + "|" + p[1];
  }

  function roughPoint(s, id) {
    if (id.charAt(0) === "D") {
      return { x: deckX[parseInt(id.substring(1), 10)], y: 0 };
    }
    const i = parseInt(id.substring(1), 10) - 1;
    return { x: s.lower[i].x, y: -2.44 };
  }

  function roughWebIndex(s, a, b) {
    const p = roughPoint(s, a);
    const q = roughPoint(s, b);
    const dx = Math.abs(p.x - q.x);
    const length = Math.sqrt(dx * dx + 2.44 * 2.44);

    if (dx < 0.15) {
      const xm = (p.x + q.x) / 2;
      return 2 + Math.min(2, Math.round(Math.abs(xm - 9) / 3.1));
    }

    let oi = 3 + Math.ceil(Math.max(0, length - 2.7) / 1.45);
    if (a === "D0" || b === "D0" || a === "D7" || b === "D7") {
      oi = Math.max(5, oi);
    }
    return Math.max(2, Math.min(8, oi));
  }

  function makeStrip(family, xs, sequence, gap) {
    const n = xs.length;
    const s = {
      family: family,
      lower: xs.map(function(x, i) {
        return { id: "B" + (i + 1), x: x };
      }),
      gap: gap === undefined ? 0.015 : gap,
      edges: []
    };

    const topSizes = [3, 3, 3, 4, 4, 5, 4];
    for (let i = 0; i < 7; i++) {
      s.edges.push({
        a: "D" + i,
        b: "D" + (i + 1),
        oi: topSizes[i],
        role: "top"
      });
    }

    const bottomDefaults = {
      2: [8],
      3: [7, 7],
      4: [6, 8, 6],
      5: [4, 7, 7, 4],
      6: [4, 6, 7, 6, 4],
      7: [4, 5, 6, 7, 6, 5]
    };
    const bottomSizes = bottomDefaults[n] || [];

    for (let i = 0; i < n - 1; i++) {
      s.edges.push({
        a: "B" + (i + 1),
        b: "B" + (i + 2),
        oi: bottomSizes[i] === undefined ? 5 : bottomSizes[i],
        role: "bottom"
      });
    }

    function addWeb(a, b) {
      s.edges.push({
        a: a,
        b: b,
        oi: roughWebIndex(s, a, b),
        role: "web"
      });
    }

    addWeb("D0", "B1");
    let i = 0;
    let j = 1;
    const moves = String(sequence);
    for (let k = 0; k < moves.length; k++) {
      if (moves.charAt(k) === "T") {
        i++;
        addWeb("D" + i, "B" + j);
      } else {
        j++;
        addWeb("D" + i, "B" + j);
      }
    }
    return s;
  }

  function setTop(s, sizes) {
    for (let i = 0; i < 7; i++) s.edges[i].oi = sizes[i];
  }

  function setBottom(s, sizes) {
    for (let i = 0; i < sizes.length; i++) s.edges[7 + i].oi = sizes[i];
  }

  function setByPair(s, pairs) {
    const wanted = Object.create(null);
    for (let i = 0; i < pairs.length; i++) {
      wanted[edgeKey(pairs[i][0], pairs[i][1])] = pairs[i][2];
    }
    for (let i = 0; i < s.edges.length; i++) {
      const e = s.edges[i];
      const k = edgeKey(e.a, e.b);
      if (wanted[k] !== undefined) e.oi = wanted[k];
    }
  }

  function cloneState(s) {
    return {
      family: s.family,
      gap: s.gap,
      lower: s.lower.map(function(n) {
        return { id: n.id, x: n.x };
      }),
      edges: s.edges.map(function(e) {
        return { a: e.a, b: e.b, oi: e.oi, role: e.role };
      })
    };
  }

  const p6 = makeStrip(
    "P6",
    deckX.slice(1, 7),
    "TBTBTBTTBTBT",
    0.015
  );
  setTop(p6, [3, 3, 3, 4, 4, 5, 4]);
  setBottom(p6, [4, 6, 7, 6, 4]);
  setByPair(p6, [
    ["D0", "B1", 5],
    ["D1", "B1", 4],
    ["D1", "B2", 4],
    ["D2", "B2", 3],
    ["D2", "B3", 4],
    ["D3", "B3", 3],
    ["D3", "B4", 4],
    ["D4", "B4", 2],
    ["D5", "B4", 4],
    ["D5", "B5", 3],
    ["D6", "B5", 4],
    ["D6", "B6", 4],
    ["D7", "B6", 5]
  ]);

  const p5 = makeStrip(
    "P5",
    [deckX[1], deckX[2], 9, deckX[5], deckX[6]],
    "TBTBTTTBTBT",
    0.015
  );
  setTop(p5, [3, 3, 3, 4, 4, 5, 4]);
  setBottom(p5, [4, 7, 7, 4]);
  setByPair(p5, [
    ["D0", "B1", 5],
    ["D1", "B1", 4],
    ["D1", "B2", 4],
    ["D2", "B2", 3],
    ["D2", "B3", 4],
    ["D3", "B3", 3],
    ["D4", "B3", 3],
    ["D5", "B3", 4],
    ["D5", "B4", 3],
    ["D6", "B4", 4],
    ["D6", "B5", 4],
    ["D7", "B5", 5]
  ]);

  const p4 = makeStrip(
    "P4",
    [2.571, 6.429, 11.571, 15.429],
    "TBTTBTTTBT",
    0.015
  );
  setTop(p4, [3, 3, 3, 4, 4, 5, 4]);
  setBottom(p4, [6, 8, 6]);
  setByPair(p4, [
    ["D0", "B1", 5],
    ["D1", "B1", 5],
    ["D1", "B2", 4],
    ["D2", "B2", 4],
    ["D3", "B2", 4],
    ["D3", "B3", 5],
    ["D4", "B3", 4],
    ["D5", "B3", 4],
    ["D6", "B3", 5],
    ["D6", "B4", 5],
    ["D7", "B4", 5]
  ]);

  const p2 = makeStrip(
    "P2",
    [5, 13],
    "TTTTBTTT",
    0.015
  );

  const p3a = makeStrip(
    "P3A",
    [3, 9, 15],
    "TTBTTBTTT",
    0.015
  );

  const p3b = makeStrip(
    "P3B",
    [3, 9, 15],
    "TTTBTTBTT",
    0.015
  );

  const p7x = [];
  for (let i = 0; i < 7; i++) p7x.push((i + 0.5) * 18 / 7);

  const p7a = makeStrip(
    "P7A",
    p7x,
    "TBTBTBTBTBTBT",
    0.015
  );

  const p7b = makeStrip(
    "P7B",
    p7x,
    "BTBTBTBTBTBTT",
    0.015
  );

  const p6a = makeStrip(
    "P6A",
    deckX.slice(1, 7),
    "TTBTBTBTBTBT",
    0.015
  );

  const p6b = makeStrip(
    "P6B",
    deckX.slice(1, 7),
    "TBTBTTBTBTBT",
    0.015
  );

  function geometry(s) {
    const coords = Object.create(null);
    for (let i = 0; i < deckX.length; i++) {
      coords["D" + i] = { x: deckX[i], y: 0 };
    }
    for (let i = 0; i < s.lower.length; i++) {
      coords[s.lower[i].id] = { x: s.lower[i].x, y: -2.44 };
    }

    for (let iter = 0; iter < 10; iter++) {
      const nextY = [];
      for (let i = 0; i < s.lower.length; i++) {
        const id = s.lower[i].id;
        let radius = 0;

        for (let j = 0; j < s.edges.length; j++) {
          const e = s.edges[j];
          if (e.a !== id && e.b !== id) continue;

          const other = e.a === id ? e.b : e.a;
          const p = coords[id];
          const q = coords[other];
          if (!p || !q) continue;

          const dx = Math.abs(p.x - q.x);
          const dy = p.y - q.y;
          const length = Math.sqrt(dx * dx + dy * dy);
          if (length > 1e-9) {
            radius = Math.max(
              radius,
              sections[e.oi].depth / 2000 * dx / length
            );
          }
        }
        nextY.push(-2.77 + radius + s.gap);
      }

      for (let i = 0; i < s.lower.length; i++) {
        coords[s.lower[i].id].y = nextY[i];
      }
    }
    return coords;
  }

  function makeDesign(s) {
    const coords = geometry(s);
    const used = Object.create(null);
    const degrees = Object.create(null);
    const rays = Object.create(null);
    const members = [];

    function addRay(id, other) {
      const p = coords[id];
      const q = coords[other];
      if (!p || !q) return false;
      if (!rays[id]) rays[id] = [];
      rays[id].push(Math.atan2(q.y - p.y, q.x - p.x));
      return true;
    }

    for (let i = 0; i < s.edges.length; i++) {
      const e = s.edges[i];
      if (e.oi < 0 || e.oi >= sections.length) return null;

      const p = coords[e.a];
      const q = coords[e.b];
      if (!p || !q) return null;

      const dx = q.x - p.x;
      const dy = q.y - p.y;
      const length = Math.sqrt(dx * dx + dy * dy);
      if (length < 0.4 - 1e-9 || length > 11.7 + 1e-9) return null;

      const radius =
        sections[e.oi].depth / 2000 * Math.abs(dx) / length;
      if (Math.min(p.y, q.y) - radius < -2.77 - 1e-7 ||
          Math.max(p.y, q.y) + radius > 2.03 + 1e-7) {
        return null;
      }

      used[e.a] = true;
      used[e.b] = true;
      degrees[e.a] = (degrees[e.a] || 0) + 1;
      degrees[e.b] = (degrees[e.b] || 0) + 1;
      if (!addRay(e.a, e.b) || !addRay(e.b, e.a)) return null;
      members.push([e.a, e.b, sections[e.oi].spec]);
    }

    const ids = Object.keys(used);
    if (ids.length > 80 || members.length > 250) return null;

    const minAngle = 15 * Math.PI / 180;
    for (let i = 0; i < ids.length; i++) {
      const id = ids[i];
      const p = coords[id];
      if (!p || p.x < -1e-8 || p.x > 18 + 1e-8 ||
          p.y < -2.77 - 1e-8 || p.y > 2.03 + 1e-8 ||
          degrees[id] > 8) {
        return null;
      }

      const a = rays[id] || [];
      for (let j = 0; j < a.length; j++) {
        for (let k = j + 1; k < a.length; k++) {
          let d = Math.abs(a[j] - a[k]);
          if (d > Math.PI) d = 2 * Math.PI - d;
          if (d < minAngle - 1e-8) return null;
        }
      }
    }

    const nodes = [];
    for (let i = 0; i < s.lower.length; i++) {
      const id = s.lower[i].id;
      if (used[id]) {
        nodes.push({
          id: id,
          x: coords[id].x,
          y: coords[id].y,
          joint: "pin"
        });
      }
    }

    return {
      note: note,
      nodes: nodes,
      joints: {},
      members: members
    };
  }

  function estimatedMass(s) {
    const coords = geometry(s);
    const used = Object.create(null);
    let mass = 0;

    for (let i = 0; i < s.edges.length; i++) {
      const e = s.edges[i];
      used[e.a] = true;
      used[e.b] = true;
      const p = coords[e.a];
      const q = coords[e.b];
      const dx = p.x - q.x;
      const dy = p.y - q.y;
      const length = Math.sqrt(dx * dx + dy * dy);
      mass += sections[e.oi].linearMass * (length + 0.7);
    }

    return mass + 12 * Object.keys(used).length;
  }

  function fatigueRatio(x) {
    if (isNum(x)) return x > 2 ? x / 4.678 : x;

    if (Array.isArray(x)) {
      let best = null;
      for (let i = 0; i < x.length; i++) {
        const r = fatigueRatio(x[i]);
        if (isNum(r) && (best === null || r > best)) best = r;
      }
      return best;
    }

    if (!x || typeof x !== "object") return null;

    let util = null;
    let stress = null;
    let limit = null;

    for (const key of Object.keys(x)) {
      const k = key.toLowerCase();
      const value = x[key];
      if (!isNum(value)) continue;

      if (k.includes("util") || k.includes("ratio") ||
          k.includes("unity") || k.includes("usage")) {
        util = util === null ? value : Math.max(util, value);
      } else if (k.includes("limit") || k.includes("allow") ||
                 k.includes("capacity")) {
        limit = value;
      } else if (k.includes("stress") || k.includes("range") ||
                 k.includes("delta")) {
        stress = value;
      }
    }

    if (util !== null) return util;
    if (stress !== null && limit !== null && limit > 0) {
      return stress / limit;
    }
    if (stress !== null) return stress / 4.678;

    let best = null;
    for (const key of Object.keys(x)) {
      const r = fatigueRatio(x[key]);
      if (isNum(r) && (best === null || r > best)) best = r;
    }
    return best;
  }

  function metrics(r, s) {
    let uls = isNum(r.maxUtil) ? r.maxUtil : null;
    if (Array.isArray(r.cases)) {
      for (let i = 0; i < r.cases.length; i++) {
        const u = r.cases[i] && r.cases[i].maxUtil;
        if (isNum(u) && (uls === null || u > uls)) uls = u;
      }
    }
    if (uls === null) uls = Infinity;

    let fatigue = fatigueRatio(r.fatigueWorst);
    if (!isNum(fatigue) && Array.isArray(r.members)) {
      fatigue = null;
      for (let i = 0; i < r.members.length; i++) {
        const m = r.members[i];
        if (m &&
            String(m.mode || "").toLowerCase().includes("fatigue") &&
            isNum(m.util)) {
          fatigue = fatigue === null ? m.util : Math.max(fatigue, m.util);
        }
      }
    }
    if (!isNum(fatigue)) fatigue = Infinity;

    let sag = isNum(r.sag) ? Math.abs(r.sag) : null;
    if (Array.isArray(r.cases)) {
      for (let i = 0; i < r.cases.length; i++) {
        const v = r.cases[i] && r.cases[i].sag;
        if (isNum(v)) {
          sag = sag === null ? Math.abs(v) : Math.max(sag, Math.abs(v));
        }
      }
    }

    const sagLimit = isNum(r.sagLimit) && r.sagLimit > 0 ? r.sagLimit : 45;
    const sagRatio = sag === null ? Infinity : sag / Math.min(36, sagLimit);
    const fMin = isNum(r.fMin) && r.fMin > 0 ? r.fMin : 4.5;
    const frequency = isNum(r.frequency) && r.frequency > 0 ? r.frequency : 0;

    const q = Math.max(
      uls / 0.75,
      fatigue / 0.92,
      sagRatio,
      frequency > 0 ? 1.2 * fMin / frequency : Infinity
    );

    let failure = "";
    if (typeof r.failure === "string") failure = r.failure.toLowerCase().trim();
    const failureOK = failure === "" || failure === "none" ||
      failure === "ok" || failure === "pass" || failure === "passed" ||
      failure === "no failure";

    return {
      q: q,
      safe: r.ok === true && failureOK && q <= 1,
      mass: isNum(r.mass) ? r.mass : estimatedMass(s)
    };
  }

  const seen = Object.create(null);
  let best = null;

  function stateKey(s) {
    return s.family + "|" + s.gap.toFixed(4) + "|" +
      s.lower.map(function(n) {
        return n.id + "@" + n.x.toFixed(4);
      }).join(",") + "|" +
      s.edges.map(function(e) {
        return edgeKey(e.a, e.b) + ":" + e.oi;
      }).join("|");
  }

  function evaluate(s) {
    const key = stateKey(s);
    if (Object.prototype.hasOwnProperty.call(seen, key)) return seen[key];
    if (!withinBudget()) return null;

    const snap = cloneState(s);
    const d = makeDesign(snap);
    if (!d) {
      seen[key] = null;
      return null;
    }

    let r;
    try {
      r = analyse(d);
      calls++;
    } catch (e) {
      calls++;
      seen[key] = null;
      return null;
    }

    if (!r || r.error) {
      seen[key] = null;
      return null;
    }

    const m = metrics(r, snap);
    const entry = {
      state: snap,
      design: d,
      result: r,
      q: m.q,
      safe: m.safe,
      mass: m.mass
    };
    seen[key] = entry;

    if (entry.safe &&
        (!best || entry.mass < best.mass - 0.01 ||
         (Math.abs(entry.mass - best.mass) < 0.01 && entry.q < best.q))) {
      best = entry;
    }
    return entry;
  }

  function normalizedMemberId(id) {
    const text = String(id || "")
      .replace(/[–—]/g, "-")
      .replace(/\s*\([^)]*\)\s*$/, "");
    const parts = text.split("-");
    if (parts.length !== 2) return text;
    parts.sort();
    return parts[0] + "|" + parts[1];
  }

  function memberUtil(entry, edge) {
    const list = entry.result && entry.result.members;
    if (!Array.isArray(list)) return 1;

    const target = normalizedMemberId(edge.a + "-" + edge.b);
    let util = null;
    for (let i = 0; i < list.length; i++) {
      const m = list[i];
      if (!m) continue;
      let id = m.id || m.member || "";
      if (!id && m.a && m.b) id = m.a + "-" + m.b;
      if (normalizedMemberId(id) === target && isNum(m.util)) {
        util = util === null ? m.util : Math.max(util, m.util);
      }
    }
    return util === null ? 1 : util;
  }

  function repair(entry, stopAt) {
    let current = entry;

    for (let pass = 0; pass < 3 &&
                        withinBudget() && calls < stopAt; pass++) {
      const order = [];
      for (let i = 0; i < current.state.edges.length; i++) {
        const e = current.state.edges[i];
        if (e.oi < sections.length - 1) {
          order.push({ index: i, util: memberUtil(current, e) });
        }
      }
      order.sort(function(a, b) { return b.util - a.util; });

      let winner = null;
      for (let i = 0; i < order.length &&
                      withinBudget() && calls < stopAt; i++) {
        const trial = cloneState(current.state);
        trial.edges[order[i].index].oi++;
        const e = evaluate(trial);
        if (!e) continue;

        if (e.safe) {
          if (!winner || !winner.safe || e.mass < winner.mass) winner = e;
        } else if ((!winner || !winner.safe) &&
                   e.q < current.q - 1e-5 &&
                   (!winner || e.q < winner.q)) {
          winner = e;
        }
      }

      if (!winner) break;
      current = winner;
      if (current.safe) break;
    }
    return current;
  }

  function optimize(entry, allowance) {
    if (!entry) return entry;
    const stopAt = Math.min(MAX_CALLS, calls + allowance);
    let current = entry;

    if (!current.safe && isNum(current.q) && current.q < 1.75) {
      current = repair(current, stopAt);
    }
    if (!current || !current.safe) return current;

    for (let pass = 0; pass < 3 &&
                        withinBudget() && calls < stopAt; pass++) {
      const coords = geometry(current.state);
      const order = [];

      for (let i = 0; i < current.state.edges.length; i++) {
        const e = current.state.edges[i];
        if (e.oi <= 0) continue;

        const p = coords[e.a];
        const q = coords[e.b];
        const dx = p.x - q.x;
        const dy = p.y - q.y;
        const length = Math.sqrt(dx * dx + dy * dy);
        const saving =
          (sections[e.oi].linearMass -
           sections[e.oi - 1].linearMass) * (length + 0.7);
        order.push({ index: i, saving: saving });
      }
      order.sort(function(a, b) { return b.saving - a.saving; });

      let winner = null;
      for (let i = 0; i < order.length &&
                      withinBudget() && calls < stopAt; i++) {
        const trial = cloneState(current.state);
        trial.edges[order[i].index].oi--;
        const e = evaluate(trial);

        if (e && e.safe && e.mass < current.mass - 0.03 &&
            (!winner || e.mass < winner.mass ||
             (Math.abs(e.mass - winner.mass) < 0.01 && e.q < winner.q))) {
          winner = e;
        }
      }

      if (!winner) break;
      current = winner;
    }
    return current;
  }

  function searchSeed(s, allowance) {
    if (!withinBudget()) return;
    const entry = evaluate(s);
    if (!entry) return;
    if (entry.safe || (isNum(entry.q) && entry.q < 1.75)) {
      optimize(entry, allowance);
    }
  }

  const seeds = [
    { state: p6, budget: 26 },
    { state: p2, budget: 38 },
    { state: p3a, budget: 32 },
    { state: p3b, budget: 30 },
    { state: p7a, budget: 40 },
    { state: p7b, budget: 32 },
    { state: p6a, budget: 25 },
    { state: p6b, budget: 25 },
    { state: p5, budget: 24 },
    { state: p4, budget: 24 }
  ];

  for (let i = 0; i < seeds.length && withinBudget(); i++) {
    searchSeed(seeds[i].state, seeds[i].budget);
  }

  if (best && withinBudget()) {
    const source = cloneState(best.state);
    const variants = [];
    const n = source.lower.length;

    for (let i = 0; i < Math.floor(n / 2); i++) {
      for (const delta of [-0.12, 0.12]) {
        const trial = cloneState(source);
        trial.lower[i].x += delta;
        trial.lower[n - 1 - i].x -= delta;
        variants.push(trial);
      }
    }

    for (const factor of [0.985, 1.015]) {
      const trial = cloneState(source);
      trial.lower = trial.lower.map(function(node) {
        return {
          id: node.id,
          x: 9 + (node.x - 9) * factor
        };
      });
      variants.push(trial);
    }

    const refineStop = Math.min(MAX_CALLS, calls + Math.min(70, MAX_CALLS - calls));
    for (let i = 0; i < variants.length &&
                    withinBudget() && calls < refineStop; i++) {
      const e = evaluate(variants[i]);
      if (e && e.safe && e.mass <= best.mass * 1.10) {
        optimize(e, Math.min(10, refineStop - calls));
      }
    }
  }

  if (best) return best.design;
  return makeDesign(p6);
}

function design(site, analyse) {
  // Geometry: deck chord D0..D7 at y=0 (existing nodes).
  // Top chord T0..T6 at panel midpoints (above deck, low over the crane zone).
  // Bottom chord B0..B6 at panel midpoints, y=-2.7.
  // Every T_k and B_k connects to D_k and D_{k+1}; all joints pinned.
  // Five member groups are sized by a search over CHS sections (S690 / S355).
  const names = ["CHS33.7x2.6","CHS42.4x3.2","CHS48.3x3.2","CHS60.3x3.2","CHS60.3x4",
    "CHS76.1x3.2","CHS76.1x4","CHS88.9x4","CHS88.9x5","CHS114.3x4","CHS114.3x5",
    "CHS139.7x5","CHS139.7x6.3","CHS168.3x5","CHS168.3x6.3","CHS193.7x6.3","CHS193.7x8",
    "CHS219.1x8","CHS244.5x8","CHS273x10","CHS323.9x10","CHS355.6x12.5","CHS406.4x12.5","CHS457x16"];
  const opts = [];
  for (const n of names) { opts.push("S690 " + n); opts.push("S355 " + n); }

  const topY = [2.0, 2.0, 2.0, 2.0, 1.22, 1.2, 1.2];
  const X = k => (k + 0.5) * 18 / 7;
  const nodes = [];
  for (let k = 0; k < 7; k++) {
    nodes.push({ id: "T" + k, x: +X(k).toFixed(4), y: topY[k], joint: "pin" });
    nodes.push({ id: "B" + k, x: +X(k).toFixed(4), y: -2.7, joint: "pin" });
  }

  function build(a) {
    const m = [];
    for (let k = 0; k < 7; k++) m.push(["D" + k, "D" + (k + 1), opts[a[0]]]);      // deck chord
    for (let k = 0; k < 6; k++) m.push(["T" + k, "T" + (k + 1), opts[a[1]]]);      // top chord
    for (let k = 0; k < 7; k++) {                                                   // top webs
      m.push(["T" + k, "D" + k, opts[a[2]]]);
      m.push(["T" + k, "D" + (k + 1), opts[a[2]]]);
    }
    for (let k = 0; k < 6; k++) m.push(["B" + k, "B" + (k + 1), opts[a[3]]]);      // bottom chord
    for (let k = 0; k < 7; k++) {                                                   // bottom webs
      m.push(["B" + k, "D" + k, opts[a[4]]]);
      m.push(["B" + k, "D" + (k + 1), opts[a[4]]]);
    }
    return {
      note: "Double-level Warren: deck chord, top chord above (dips to 1.2 m over crane zone), bottom chord at -2.7 m, all pinned, CHS sizes searched.",
      nodes: nodes,
      joints: {},
      members: m
    };
  }

  const cache = new Map();
  let calls = 0;
  function good(a) {
    const key = a.join(",");
    if (cache.has(key)) return cache.get(key);
    calls++;
    let r = null;
    try { r = analyse(build(a)); } catch (e) { r = null; }
    const ok = !!r && !r.error && r.ok === true &&
      (typeof r.maxUtil !== "number" || r.maxUtil <= 0.9);
    cache.set(key, ok);
    return ok;
  }

  // Start heavy (known to be intended to pass), then reduce each group by binary search.
  const top = opts.length - 1;
  let a = [top, top, top, top, top];
  for (let round = 0; round < 2; round++) {
    for (let g = 0; g < 5; g++) {
      let lo = 0, hi = a[g];
      while (lo < hi) {
        if (calls > 300) break;
        const mid = (lo + hi) >> 1;
        const t = a.slice();
        t[g] = mid;
        if (good(t)) hi = mid; else lo = mid + 1;
      }
      a[g] = hi;
    }
  }
  return build(a);
}

function design(site, analyse) {
