  let calls = 0;
  const NOTE = "Double-level Warren (7 panels, top chord lowered over crane zone, bottom chord at -2.75 m) with member sizes set by fully-stressed iteration on analyse(), trying wire-rope tension-only chords/webs, then a one-step polish.";

  const CHS = [
