  function copy(st) {
    return st.map(s => ({ a: s.a, b: s.b, g: s.g, t: s.t, i: s.i }));
  }

  function makeDesign(st, note) {
    return {
      note: note,
      nodes: nodes.map(n => ({ id: n.id, x: n.x, y: n.y, joint: n.joint })),
      joints: {},
      members: st.map(s => [s.a, s.b, PREFIX[s.t] + LIST[s.t][s.i][0]])
    };
  }

  function run(d) {
    calls++;
    try {
      const r = analyse(d);
      if (!r || r.error) return null;
      return r;
    } catch (e) {
      return null;
    }
  }

  function feasible(r) {
    return !!r && r.ok === true && typeof r.maxUtil === "number" && r.maxUtil <= LIMIT;
  }

  function utilList(r, st) {
    const map = {};
    if (r.members) for (const m of r.members) map[m.id] = m.util;
    let found = 0;
    const out = st.map(s => {
      let u = map[s.a + "-" + s.b];
      if (u === undefined) u = map[s.b + "-" + s.a];
      if (u === undefined) return null;
      found++;
      if (typeof u !== "number" || !isFinite(u)) return 9;
      return u;
    });
    return found > 0 ? out : null;
  }

