  const BASE = [
    ["D0","D1","TIMBER115x225"], ["D1","D2","TIMBER90x180"], ["D2","D3","TIMBER90x180"],
    ["D3","D4","TIMBER90x180"], ["D4","D5","TIMBER90x180"], ["D5","D6","TIMBER115x225"],
    ["D6","D7","TIMBER115x225"],
    ["T0","T1","TIMBER115x225"], ["T1","T2","TIMBER140x270"], ["T2","T3","TIMBER160x315"],
    ["T3","T4","TIMBER190x360"], ["T4","T5","TIMBER140x270"], ["T5","T6","TIMBER115x225"],
    ["T0","D0","TIMBER115x225"], ["T0","D1","TIMBER90x180"], ["T1","D1","TIMBER140x270"],
    ["T1","D2","TIMBER115x225"], ["T2","D2","TIMBER115x225"], ["T2","D3","TIMBER115x225"],
    ["T3","D3","TIMBER90x180"], ["T3","D4","TIMBER90x180"], ["T4","D4","TIMBER90x180"],
    ["T4","D5","TIMBER115x225"], ["T5","D5","TIMBER90x180"], ["T5","D6","TIMBER90x180"],
    ["T6","D6","TIMBER90x180"], ["T6","D7","TIMBER90x180"],
    ["B0","B1","TIMBER140x270"], ["B1","B2","TIMBER160x315"], ["B2","B3","TIMBER190x360"],
    ["B3","B4","TIMBER190x360"], ["B4","B5","TIMBER190x360"], ["B5","B6","TIMBER140x270"],
    ["B0","D0","TIMBER160x315"], ["B0","D1","TIMBER160x315"], ["B1","D1","TIMBER115x225"],
    ["B1","D2","TIMBER140x270"], ["B2","D2","TIMBER115x225"], ["B2","D3","TIMBER115x225"],
    ["B3","D3","TIMBER140x270"], ["B3","D4","TIMBER140x270"], ["B4","D4","TIMBER115x225"],
    ["B4","D5","TIMBER115x225"], ["B5","D5","TIMBER140x270"], ["B5","D6","TIMBER140x270"],
    ["B6","D6","TIMBER160x315"], ["B6","D7","TIMBER160x315"]
  ];

  const r4 = v => Math.round(v * 10000) / 10000;
  const topY = [2.02, 2.02, 2.02, 2.02, 1.22, 1.2, 1.2];
  const NODES = [];
  for (let k = 0; k < 7; k++) {
    const x = r4((k + 0.5) * 18 / 7);
    NODES.push({ id: "T" + k, x: x, y: topY[k], joint: "pin" });
    NODES.push({ id: "B" + k, x: x, y: -2.75, joint: "pin" });
  }

  function tIndex(name) {
    for (let j = 0; j < TIM.length; j++) if (TIM[j][0] === name) return j;
    return 0;
  }

  function copy(st) { return st.map(s => ({ a: s.a, b: s.b, i: s.i })); }

  function makeDesign(st, note) {
    return {
      note: note,
      nodes: NODES.map(n => ({ id: n.id, x: n.x, y: n.y, joint: n.joint })),
      joints: {},
      members: st.map(s => [s.a, s.b, "GL28 " + TIM[s.i][0]])
    };
  }

  function evaluate(st) {
    if (calls >= MAXCALLS || Date.now() - t0 > 70000) return null;
    calls++;
    let r;
    try { r = analyse(makeDesign(st, NOTE)); } catch (e) { return null; }
    if (!r || r.error || !Array.isArray(r.members)) return null;
    const map = {};
    for (const m of r.members) map[m.id] = m;
    let feas = (r.ok === true);
    if (typeof r.maxUtil === "number" && r.maxUtil > 1) feas = false;
    const info = [];
    for (const q of st) {
      const m = map[q.a + "-" + q.b] || map[q.b + "-" + q.a];
      if (!m) return null;
      const u = Number(m.util);
      if (!isFinite(u)) return null;
      const fat = /fatigue/i.test(String(m.mode || ""));
      const lim = fat ? FAT_LIM : STAT_LIM;
      if (u > lim) feas = false;
      info.push({ u: u, fat: fat, lim: lim });
    }
    return { feas: feas, mass: Number(r.mass), info: info };
  }

  // bump over-utilised members to a larger section (in place)
  function repair(st, ev) {
    let ch = false;
    for (let q = 0; q < st.length; q++) {
      const f = ev.info[q];
      if (f.u <= f.lim) continue;
      const tgt = f.fat ? FAT_TGT : STAT_TGT;
      const want = TIM[st[q].i][1] * f.u / tgt;
      let j = TIM.length - 1;
      for (let k = 0; k < TIM.length; k++) {
        if (TIM[k][1] >= want) { j = k; break; }
      }
      if (j <= st[q].i) j = st[q].i + 1;
      if (j > TIM.length - 1) j = TIM.length - 1;
      if (j !== st[q].i) { st[q].i = j; ch = true; }
    }
    return ch;
  }

  function settle(st, ev, tries) {
    let e = ev;
    for (let t = 0; t < tries && e && !e.feas; t++) {
      if (!repair(st, e)) break;
      e = evaluate(st);
    }
    return e;
  }

  // ---- start from attempt-6 sizes ----
  const base = BASE.map(e => ({ a: e[0], b: e[1], i: tIndex(e[2]) }));
  let cur = copy(base);
  let ev = evaluate(cur);
  if (!ev) return makeDesign(base, NOTE);
  if (!ev.feas) ev = settle(cur, ev, 4);
  if (!ev || !ev.feas) return makeDesign(base, NOTE);
  let curMass = ev.mass;

  // ---- greedy deletion, least-loaded members first ----
  const order = cur.map((s, q) => ({ key: s.a + "|" + s.b, u: ev.info[q].u }))
                   .sort((x, y) => x.u - y.u);
  for (const o of order) {
    if (calls >= MAXCALLS - 8 || Date.now() - t0 > 60000) break;
    const idx = cur.findIndex(s => (s.a + "|" + s.b) === o.key);
    if (idx < 0) continue;
    const trial = cur.filter((s, q) => q !== idx).map(s => ({ a: s.a, b: s.b, i: s.i }));
    let e2 = evaluate(trial);
    if (!e2) continue;
    e2 = settle(trial, e2, 3);
    if (e2 && e2.feas && e2.mass < curMass) {
      cur = trial;
      ev = e2;
      curMass = e2.mass;
    }
  }

  // ---- one-step polish per member ----
  for (let pass = 0; pass < 2; pass++) {
    let improved = false;
    for (let q = 0; q < cur.length; q++) {
      if (cur[q].i <= 0) continue;
      if (calls >= MAXCALLS || Date.now() - t0 > 75000) break;
      const trial = copy(cur);
      trial[q].i -= 1;
      const e3 = evaluate(trial);
      if (e3 && e3.feas && e3.mass < curMass) {
        cur = trial;
        ev = e3;
        curMass = e3.mass;
        improved = true;
      }
    }
    if (!improved) break;
  }

  return makeDesign(cur, NOTE);
}

function design(site, analyse) {
  const t0 = Date.now();
  const MAXCALLS = 320;
  const TLIM = 70000;
  let calls = 0;
  const NOTE = "Attempt-7 and attempt-6 double-level Warren re-sized against worst-draw GL28 buckling (strength 85%, E 85%, imperfection 1.5, +3% demand) and wind moments, then greedy deletion and one-step step-down on the robust mass.";

  const FAT_LIM = 0.92;
  const ROB_LIM = 0.97;
  const DEM = 1.03;
  const MOM = 0.03;

  // [id, A cm2, Iz cm4 (weak axis), Wz cm3, depth m]
  const TIM = [
    ["TIMBER90x180", 162, 1093.5, 243, 0.180],
    ["TIMBER115x225", 258.75, 2851.6, 495.9, 0.225],
    ["TIMBER140x270", 378, 6174, 882, 0.270],
    ["TIMBER160x315", 504, 10752, 1344, 0.315],
    ["TIMBER190x360", 684, 20577, 2166, 0.360],
    ["TIMBER190x450", 855, 25721.3, 2707.5, 0.450],
    ["TIMBER215x540", 1161, 44722.7, 4160.3, 0.540],
    ["TIMBER240x630", 1512, 72576, 6048, 0.630],
    ["TIMBER280x720", 2016, 131712, 9408, 0.720],
    ["TIMBER320x900", 2880, 245760, 15360, 0.900]
  ];
  function tIdx(name) {
    for (let j = 0; j < TIM.length; j++) if (TIM[j][0] === name) return j;
    return 0;
  }

  const r4 = v => Math.round(v * 10000) / 10000;
  const topY = [2.02, 2.02, 2.02, 2.02, 1.22, 1.2, 1.2];
  const NODES = [];
  const POS = {};
  for (let k = 0; k < 8; k++) POS["D" + k] = { x: k * 18 / 7, y: 0 };
  for (let k = 0; k < 7; k++) {
    const x = r4((k + 0.5) * 18 / 7);
    NODES.push({ id: "T" + k, x: x, y: topY[k], joint: "pin" });
    NODES.push({ id: "B" + k, x: x, y: -2.75, joint: "pin" });
    POS["T" + k] = { x: x, y: topY[k] };
    POS["B" + k] = { x: x, y: -2.75 };
  }

  const A7 = [
    ["D0","D1","TIMBER90x180"], ["D1","D2","TIMBER90x180"], ["D3","D4","TIMBER90x180"], ["D6","D7","TIMBER90x180"],
    ["T0","T1","TIMBER115x225"], ["T1","T2","TIMBER140x270"], ["T2","T3","TIMBER160x315"], ["T3","T4","TIMBER160x315"],
    ["T4","T5","TIMBER140x270"], ["T5","T6","TIMBER115x225"],
    ["T0","D0","TIMBER115x225"], ["T0","D1","TIMBER90x180"], ["T1","D1","TIMBER115x225"], ["T1","D2","TIMBER115x225"],
    ["T2","D2","TIMBER115x225"], ["T2","D3","TIMBER115x225"], ["T3","D3","TIMBER90x180"], ["T3","D4","TIMBER90x180"],
    ["T4","D4","TIMBER90x180"], ["T4","D5","TIMBER115x225"], ["T5","D5","TIMBER90x180"], ["T5","D6","TIMBER90x180"],
    ["T6","D6","TIMBER90x180"], ["T6","D7","TIMBER90x180"],
    ["B0","B1","TIMBER140x270"], ["B1","B2","TIMBER160x315"], ["B2","B3","TIMBER190x360"], ["B3","B4","TIMBER190x360"],
    ["B4","B5","TIMBER190x360"], ["B5","B6","TIMBER140x270"],
    ["B0","D0","TIMBER160x315"], ["B0","D1","TIMBER160x315"], ["B1","D1","TIMBER115x225"], ["B1","D2","TIMBER140x270"],
    ["B2","D2","TIMBER115x225"], ["B2","D3","TIMBER115x225"], ["B3","D3","TIMBER140x270"], ["B3","D4","TIMBER140x270"],
    ["B4","D4","TIMBER115x225"], ["B4","D5","TIMBER115x225"], ["B5","D5","TIMBER140x270"], ["B5","D6","TIMBER140x270"],
    ["B6","D6","TIMBER160x315"], ["B6","D7","TIMBER160x315"]
  ];

  const A6 = [
    ["D0","D1","TIMBER115x225"], ["D1","D2","TIMBER90x180"], ["D2","D3","TIMBER90x180"], ["D3","D4","TIMBER90x180"],
    ["D4","D5","TIMBER90x180"], ["D5","D6","TIMBER115x225"], ["D6","D7","TIMBER115x225"],
    ["T0","T1","TIMBER115x225"], ["T1","T2","TIMBER140x270"], ["T2","T3","TIMBER160x315"], ["T3","T4","TIMBER190x360"],
    ["T4","T5","TIMBER140x270"], ["T5","T6","TIMBER115x225"],
    ["T0","D0","TIMBER115x225"], ["T0","D1","TIMBER90x180"], ["T1","D1","TIMBER140x270"], ["T1","D2","TIMBER115x225"],
    ["T2","D2","TIMBER115x225"], ["T2","D3","TIMBER115x225"], ["T3","D3","TIMBER90x180"], ["T3","D4","TIMBER90x180"],
    ["T4","D4","TIMBER90x180"], ["T4","D5","TIMBER115x225"], ["T5","D5","TIMBER90x180"], ["T5","D6","TIMBER90x180"],
    ["T6","D6","TIMBER90x180"], ["T6","D7","TIMBER90x180"],
    ["B0","B1","TIMBER140x270"], ["B1","B2","TIMBER160x315"], ["B2","B3","TIMBER190x360"], ["B3","B4","TIMBER190x360"],
    ["B4","B5","TIMBER190x360"], ["B5","B6","TIMBER140x270"],
    ["B0","D0","TIMBER160x315"], ["B0","D1","TIMBER160x315"], ["B1","D1","TIMBER115x225"], ["B1","D2","TIMBER140x270"],
    ["B2","D2","TIMBER115x225"], ["B2","D3","TIMBER115x225"], ["B3","D3","TIMBER140x270"], ["B3","D4","TIMBER140x270"],
    ["B4","D4","TIMBER115x225"], ["B4","D5","TIMBER115x225"], ["B5","D5","TIMBER140x270"], ["B5","D6","TIMBER140x270"],
    ["B6","D6","TIMBER160x315"], ["B6","D7","TIMBER160x315"]
  ];

  function toSt(list) { return list.map(e => ({ a: e[0], b: e[1], i: tIdx(e[2]) })); }
  function copy(st) { return st.map(s => ({ a: s.a, b: s.b, i: s.i })); }
  function over() { return calls >= MAXCALLS || Date.now() - t0 > TLIM; }

  function segLen(a, b) {
    const p = POS[a], q = POS[b];
    return Math.sqrt((p.x - q.x) * (p.x - q.x) + (p.y - q.y) * (p.y - q.y));
  }

  // robust utilisation: worst draw of strength (0.85..1.2), E (0.85..1.15),
  // imperfection 1.5, thickness 0.98, demand +3%, wind moment about weak axis
  function robU(s, Nc, Nt) {
    const m = TIM[s.i];
    const L = segLen(s.a, s.b);
    const A = m[1] * 1e-4 * 0.98;
    const I = m[2] * 1e-8 * 0.96;
    const Wz = m[3] * 1e-6;
    const h = m[4];
    let u = DEM * Nt / (A * 0.85 * 22000 / 1.05);
    for (const sd of [0.85, 1.2]) {
      for (const ed of [0.85, 1.15]) {
        const fy = 22000 * sd;
        const E = 12.6e6 * ed;
        const Ncr = Math.PI * Math.PI * E * I / (L * L);
        const lam = Math.sqrt(A * fy / Ncr);
        const Phi = 0.5 * (1 + 0.49 * 1.5 * (lam - 0.2) + lam * lam);
        const chi = Math.min(1, 1 / (Phi + Math.sqrt(Math.max(0, Phi * Phi - lam * lam))));
        const Nb = chi * A * fy / 1.05;
        u = Math.max(u, DEM * Nc / Nb);
      }
    }
    const Mz = 1.5 * 1.01 * 2.0 * (h + 0.056) * L * L / 8;
    const MzRd = Wz * 0.85 * 22000 / 1.05;
    return u + Mz / MzRd + MOM;
  }

  function makeDesign(st) {
    return {
      note: NOTE,
      nodes: NODES.map(n => ({ id: n.id, x: n.x, y: n.y, joint: n.joint })),
      joints: {},
      members: st.map(s => [s.a, s.b, "GL28 " + TIM[s.i][0]])
    };
  }

  function evaluate(st) {
    if (over()) return null;
    calls++;
    let r;
    try { r = analyse(makeDesign(st)); } catch (e) { return null; }
    if (!r || r.error || !Array.isArray(r.members)) return null;
    const mass = Number(r.mass);
    if (!isFinite(mass)) return null;
    const map = {};
    for (const m of r.members) map[m.id] = m;
    let feas = (r.ok === true);
    if (typeof r.maxUtil === "number" && r.maxUtil > 1) feas = false;
    const U = [], R = [];
    for (const s of st) {
      const m = map[s.a + "-" + s.b] || map[s.b + "-" + s.a];
      if (!m) return null;
      const u = Number(m.util);
      if (!isFinite(u)) return null;
      const Nc = Math.abs(Number(m.compression) || 0);
      const Nt = Math.abs(Number(m.tension) || 0);
      const ur = robU(s, Nc, Nt);
      if (u > FAT_LIM || ur > ROB_LIM) feas = false;
      U.push(ur);
      R.push(u);
    }
    return { feas: feas, mass: mass, U: U, R: R };
  }

  function slack(ev, q) { return Math.max(ev.U[q] / ROB_LIM, ev.R[q] / FAT_LIM); }

  function repair(st, ev) {
    let ch = false;
    for (let q = 0; q < st.length; q++) {
      const u = ev.R[q], ur = ev.U[q];
      if (u <= FAT_LIM && ur <= ROB_LIM) continue;
      const rq = Math.max(u / 0.9, ur / 0.95);
      const want = TIM[st[q].i][1] * rq;
      let j = TIM.length - 1;
      for (let k = 0; k < TIM.length; k++) {
        if (TIM[k][1] >= want) { j = k; break; }
      }
      if (j <= st[q].i) j = st[q].i + 1;
      if (j > TIM.length - 1) j = TIM.length - 1;
      if (j !== st[q].i) { st[q].i = j; ch = true; }
    }
    return ch;
  }

  function runStart(st0) {
    let cur = copy(st0);
    let ev = evaluate(cur);
    for (let it = 0; it < 8 && ev && !ev.feas; it++) {
      if (!repair(cur, ev)) break;
      ev = evaluate(cur);
    }
    if (!ev || !ev.feas) return null;
    let curMass = ev.mass;

    // deletion pass, least-loaded first
    const keys = cur.map((s, q) => ({ key: s.a + "|" + s.b, sl: slack(ev, q) }))
                    .sort((x, y) => x.sl - y.sl)
                    .map(o => o.key);
    for (const key of keys) {
      if (over()) break;
      const idx = cur.findIndex(s => (s.a + "|" + s.b) === key);
      if (idx < 0) continue;
      const trial = copy(cur.filter((s, q) => q !== idx));
      const e2 = evaluate(trial);
      if (e2 && e2.feas && e2.mass < curMass) {
        cur = trial;
        ev = e2;
        curMass = e2.mass;
      }
    }

    // one-step size reduction passes
    for (let pass = 0; pass < 3; pass++) {
      let improved = false;
      const ord = cur.map((s, q) => q).sort((p, q) => slack(ev, p) - slack(ev, q));
      for (const q of ord) {
        if (over()) break;
        if (q >= cur.length || cur[q].i <= 0) continue;
        const trial = copy(cur);
        trial[q].i -= 1;
        const e2 = evaluate(trial);
        if (e2 && e2.feas && e2.mass < curMass) {
          cur = trial;
          ev = e2;
          curMass = e2.mass;
          improved = true;
        }
      }
      if (!improved || over()) break;
    }
    return { mass: curMass, st: cur };
  }

  const found = [];
  const rA = runStart(toSt(A7));
  if (rA) found.push(rA);
  if (!over()) {
    const rB = runStart(toSt(A6));
    if (rB) found.push(rB);
  }

  if (found.length) {
    let b = found[0];
    for (const x of found) if (x.mass < b.mass) b = x;
    return makeDesign(b.st);
  }
  return makeDesign(toSt(A7));
}
